  5: namespace App\Console\Commands;
  6: 
  7: use App\Enums\StaffRole;
  8: use App\Models\User;
  9: use App\Services\Ai\AgentOrchestrator;
 10: use App\Services\Ai\EntityResolver;
 11: use App\Services\Ai\GeminiClient;
 12: use App\Services\Ai\GeminiException;
 13: use App\Services\Ai\ToolOutcome;
 14: use App\Services\Ai\ToolRegistry;
 15: use Illuminate\Console\Command;
