 15: /**
 16:  * Admin controller serving aggregated sales, profit, inventory, supplier, and shift reports.
 17:  */
 18: class ReportController extends Controller
 19: {
 20:     public function __construct(private readonly ReportService $reports) {}
 21: 
 22:     /** @return array{0: string, 1: string} */
 23:     private function period(Request $request): array
 24:     {
 25:         $validated = $request->validate([
 26:             'from' => ['nullable', 'date_format:Y-m-d', 'required_with:to'],
 27:             'to' => ['nullable', 'date_format:Y-m-d', 'required_with:from', 'after_or_equal:from'],
 28:         ]);
 29: 
 30:         $businessNow = now(config('app.business_timezone', 'Africa/Cairo'));
 31: 
 32:         $from = $validated['from'] ?? $businessNow->copy()->startOfMonth()->toDateString();
 33:         $to = $validated['to'] ?? $businessNow->toDateString();
 34: 
 35:         if (Carbon::parse($from)->diffInDays(Carbon::parse($to)) > 365) {
 36:             throw new BusinessException('المدى الزمني للتقارير لا يتجاوز 366 يومًا شاملة البداية والنهاية.');
 37:         }
 38: 
 39:         return [$from, $to];
 40:     }
 41: 
 42:     /**
 43:      * Returns sales analytics aggregated by daily/monthly periods and optional breakdown dimensions.
 44:      *
 45:      * @param Request $request Query request containing filters
 46:      * @return JsonResponse Sales report data
 47:      */
 48:     public function sales(Request $request): JsonResponse
 49:     {
 50:         $request->validate([
 51:             'granularity' => ['nullable', 'in:daily,monthly'],
 52:             'group_by' => ['nullable', 'in:branch,channel,cashier,payment_method'],
 53:         ]);
 54:         [$from, $to] = $this->period($request);
 55: 
 56:         return response()->json(['data' => $this->reports->salesReport(
 57:             $from,
 58:             $to,
 59:             $request->input('granularity', 'daily'),
 60:             $request->input('group_by'),
 61:             app(BranchAccess::class)->restrictedBranch($request->user()),
 62:         )]);
 63:     }
 64: 
 65:     /**
 66:      * Returns inventory valuation and dead stock analysis.
 67:      *
