23:         }
24: 
25:         if (is_string($email)) {
26:             $normalized['email'] = mb_strtolower(trim($email));
27:         }
28: 
29:         // Optimistic locking is mandatory: a missing lock_version must fail
30:         // validation (422) instead of being silently backfilled.
