49:             'code' => [
50:                 'sometimes',
51:                 'required',
52:                 'string',
53:                 'max:50',
54:                 Rule::unique('branches', 'code')->ignore($branchId),
55:             ],
56:             'type' => ['sometimes', 'required', Rule::enum(BranchType::class)],
