10: 
11: class StocktakeResource extends JsonResource
12: {
13:     /**
14:      * Transform the resource into an array.
15:      *
16:      * @return array<string, mixed>
17:      */
18:     public function toArray(Request $request): array
19:     {
20:         return [
21:             'id' => $this->id,
22:             'stocktake_number' => $this->stocktake_number,
23:             'branch' => $this->whenLoaded('branch', fn () => [
24:                 'id' => $this->branch->id,
25:                 'name' => $this->branch->name,
26:             ]),
27:             'location' => $this->whenLoaded('location', fn () => $this->location ? [
28:                 'id' => $this->location->id,
29:                 'name' => $this->location->name,
30:             ] : null),
31:             'status' => $this->status,
32:             'items_count' => $this->whenCounted('items'),
33:             'created_by' => $this->created_by,
34:             'creator_name' => $this->whenLoaded('creator', fn () => $this->creator?->name),
35:             'approved_by' => $this->approved_by,
36:             'approved_at' => $this->approved_at,
37:             'notes' => $this->notes,
38:             // M6: الجرد "الأعمى" — الرصيد الدفتري والفرق للمعتمِد فقط (أو بعد
39:             // الاعتماد)، فمن يعدّ لا يرى ما يُخفي به العجز.
40:             'items' => $this->whenLoaded('items', function () use ($request) {
41:                 $reveal = $this->status === StocktakeStatus::Approved
42:                     || $request->user()?->can('stocktakes.approve');
43: 
44:                 return $this->items->map(function ($item) use ($reveal) {
45:                     $row = [
46:                         'id' => $item->id,
47:                         'product_variant_id' => $item->product_variant_id,
48:                         'sku' => $item->relationLoaded('variant') ? $item->variant?->sku : null,
49:                     ];
50:                     if ($reveal) {
51:                         $row['system_qty'] = $item->system_qty;
52:                     }
53:                     $row['counted_qty'] = $item->counted_qty;
54:                     if ($reveal) {
55:                         $row['difference'] = $item->difference;
56:                     }
57: 
58:                     return $row;
59:                 })->all();
60:             }),
61:             'created_at' => $this->created_at,
62:             'updated_at' => $this->updated_at,
63:         ];
64:     }
65: } 1: <?php
