28:     ];
29: 
30:     protected $casts = [
31:         'cost_price' => 'decimal:4', 'last_cost_price' => 'decimal:4', 'retail_price' => 'decimal:2', 'wholesale_price' => 'decimal:2', 'compare_at_price' => 'decimal:2',
32:         'weight_kg' => 'decimal:3', 'is_active' => 'boolean',
