 50:     public function register(): void
 51:     {
 52:         // scoped لا singleton: ذاكرة المستخدمين لكل طلب تعمل داخل الطلب، ولا
 53:         // تتسرب صلاحيات مستخدم لطلب آخر تحت Octane (L-6).
 54:         $this->app->scoped(BranchAccess::class);
 55:         $this->app->scoped(SettingService::class);
 56:         $this->app->scoped(StoreCatalogService::class);
 57:         $this->app->scoped(PricingService::class);
 58:         $this->app->scoped(CatalogRetailPriceObserver::class);
 59:         $this->app->scoped(\App\Services\Ai\ProposalBuilder::class);
 60:         $this->app->tag([\App\Services\Ai\Catalog\CatalogToolProvider::class, \App\Services\Ai\Inventory\InventoryToolProvider::class], 'ai.tool_providers');
 61:         $this->app->scoped(\App\Services\Ai\ToolRegistry::class, function ($app) {
 62:             return new \App\Services\Ai\ToolRegistry(
 63:                 $app->make(\App\Services\Ai\EntityResolver::class),
 64:                 $app->make(BranchAccess::class),
 65:                 $app->make(SettingService::class),
 66:                 $app->tagged('ai.tool_providers'),
 67:                 $app->make(\App\Services\Ai\ProposalBuilder::class),
