 75:     public function boot(): void
 76:     {
 77:         foreach ([ProductVariant::class, PriceListItem::class, PriceList::class,
 78:             StockLevel::class, Branch::class, Location::class] as $model) {
 79:             $model::observe(CatalogRetailPriceObserver::class);
