 81:         Event::listen(TransactionBeginning::class, function ($event): void {
 82:             app(CatalogRetailPriceObserver::class)->transactionBegan($event->connection);
 83:             if ($event->connection->transactionLevel() === 1) {
 84:                 app(SettingService::class)->resetReadSnapshot(true);
 85:             }
 86:         });
 87:         Event::listen(TransactionCommitted::class, function ($event): void {
 88:             app(CatalogRetailPriceObserver::class)->transactionFinished($event->connection);
 89:             if ($event->connection->transactionLevel() === 0) {
 90:                 app(SettingService::class)->resetReadSnapshot(true);
 91:             }
 92:         });
 93:         Event::listen(TransactionRolledBack::class, function ($event): void {
 94:             app(CatalogRetailPriceObserver::class)->transactionFinished($event->connection, true);
 95:             app(SettingService::class)->resetReadSnapshot($event->connection->transactionLevel() === 0);
 96:         });
 97:         Event::listen(JobProcessing::class, function (): void {
 98:             app(PermissionRegistrar::class)->clearPermissionsCollection();
 99:             // M9: worker نحتاجها عن نفسه — إعدادات/بادئات ترقيم قديمة من
100:             // الجاب الفات ما تفضلش عاملة تحت فيه الوحدة الجديدة.
101:             app(SettingService::class)->forgetMemoryState();
102:         });
103:         Gate::before(fn ($user) => $user instanceof User
104:             && $user->is_active && ! $user->is_system
105:             && $user->hasRole(StaffRole::SuperAdmin->value, 'staff') ? true : null);
106:         $proxies = config('app.trusted_proxies');
107:         if ($this->app->environment('production') && (! is_string($proxies) || trim($proxies) === '' || preg_match('/(?:^|,)\s*\*{1,2}\s*(?:,|$)/', $proxies))) {
108:             throw new \LogicException('Set TRUSTED_PROXIES to explicit proxy IPs/CIDRs, or none for direct access. Wildcards are not allowed in production.');
109:         }
110:         if ($this->app->environment('production') && in_array(config('cache.default'), ['file', 'array'], true)) {
111:             logger()->critical('AI agent locks require a shared atomic cache store (redis/database).');
112:         }
113:         // F17: إعدادات افتراضية خطرة في الإنتاج — روابط ورموز الاستعادة
114:         // تُكتب في السجل مع mailer=log (استيلاء على الحسابات)، وsslmode=prefer
115:         // يسمح بالرجوع لاتصال غير مشفر. فشل مبكر كحراسة TRUSTED_PROXIES.
116:         if ($this->app->environment('production') && config('mail.default') === 'log') {
117:             throw new \LogicException('Set MAIL_MAILER to a real mailer in production. The log mailer writes password-reset links and OTP codes to the log file.');
118:         }
119:         $sslmode = config('database.connections.pgsql.sslmode');
120:         if ($this->app->environment('production') && config('database.default') === 'pgsql'
121:             && in_array($sslmode, ['prefer', 'allow', 'disable'], true)) {
122:             throw new \LogicException("Set DB_SSLMODE=require (or stricter) in production. '{$sslmode}' allows a plaintext database connection.");
123:         }
