 18: final class CreateTransferDraftTool extends TransferToolBase implements UndoableTool, WriteTool
 19: {
 20:     public function name(): string
 21:     {
 22:         return 'create_transfer_draft';
 23:     }
 24: 
 25:     public function kind(): ToolKind
 26:     {
 27:         return ToolKind::Write;
