 19: final class GetStocktakeTool implements AgentTool
 20: {
 21:     public function __construct(
 22:         private EntityResolver $resolver,
 23:         private BranchAccess $branches,
 24:         private StocktakeService $stocktakes,
 25:         private InventoryPresenter $presenter,
 26:     ) {}
 27: 
 28:     public function name(): string
 29:     {
 30:         return 'get_stocktake';
 31:     }
 32: 
 33:     public function kind(): ToolKind
 34:     {
 35:         return ToolKind::Read;
 36:     }
 37: 
 38:     public function risk(): string
 39:     {
 40:         return 'low';
 41:     }
 42: 
 43:     public function permissions(): array
 44:     {
 45:         return ['stocktakes.view'];
 46:     }
 47: 
 48:     public function declaration(): array
 49:     {
 50:         return [
 51:             'name' => $this->name(),
 52:             'description' => 'تفاصيل جلسة جرد: تقدم العد والبنود.',
 53:             'parameters' => [
 54:                 'type' => 'OBJECT',
 55:                 'properties' => (object) [
 56:                     'stocktake_id' => ['type' => 'INTEGER'],
 57:                     'stocktake_number' => ['type' => 'STRING'],
 58:                     'query' => ['type' => 'STRING'],
 59:                 ],
 60:             ],
 61:         ];
 62:     }
 63: 
 64:     public function handle(User $actor, array $args): ToolOutcome
 65:     {
 66:         $args = InventoryArgs::normalize($args);
 67:         $stocktake = null;
 68:         if (! empty($args['stocktake_id'])) {
 69:             $stocktake = Stocktake::find((int) $args['stocktake_id']);
 70:         } elseif (! empty($args['stocktake_number'])) {
 71:             $stocktake = Stocktake::whereRaw('LOWER(stocktake_number) = LOWER(?)', [trim((string) $args['stocktake_number'])])->first();
 72:         } else {
 73:             $options = $this->resolver->stocktakes($actor, (string) ($args['query'] ?? ''));
 74:             if (count($options) !== 1) {
 75:                 return ToolOutcome::denied('حدد الجرد برقمه. استخدم find_entities ثم ask_user_to_choose.', auditable: false);
 76:             }
 77:             $stocktake = Stocktake::find($options[0]['id']);
 78:         }
 79:         if (! $stocktake) {
 80:             return ToolOutcome::denied('الجرد مش موجود.', auditable: false);
 81:         }
 82:         try {
 83:             $restricted = $this->branches->restrictedBranch($actor);
 84:         } catch (\Throwable) {
 85:             return ToolOutcome::denied('النطاق غير مسموح.', auditable: false);
 86:         }
 87:         if ($restricted !== null && (int) $stocktake->branch_id !== $restricted) {
 88:             return ToolOutcome::denied('الجرد خارج نطاق فرعك.', auditable: false);
 89:         }
 90:         $stocktake = $this->stocktakes->find($stocktake->id);
 91:         $stocktake->load(['items.variant:id,sku', 'branch:id,name']);
 92: 
 93:         $total = $stocktake->items->count();
 94:         $counted = $stocktake->items->whereNotNull('counted_qty')->count();
 95:         $items = $stocktake->items->take(100)->map(fn (StocktakeItem $i) => [
 96:             'variant_id' => $i->product_variant_id,
 97:             'sku' => $i->variant?->sku,
 98:             'system_qty' => $i->system_qty !== null ? (float) $i->system_qty : null,
 99:             'counted_qty' => $i->counted_qty !== null ? (float) $i->counted_qty : null,
100:             'difference' => $i->difference !== null ? (float) $i->difference : null,
101:         ])->values()->all();
102: 
103:         return $this->presenter->present($actor, [
104:             'stocktake' => [
105:                 'id' => $stocktake->id,
106:                 'stocktake_number' => $stocktake->stocktake_number,
107:                 'branch_name' => $stocktake->branch?->name,
108:                 'status' => $stocktake->status->value,
109:             ],
110:             'progress' => ['total' => $total, 'counted' => $counted],
111:             'items' => $items,
112:             'items_truncated' => $total > 100,
113:             'deep_link' => '#/stocktakes/'.$stocktake->id,
114:         ], ['type' => 'table', 'columns' => ['الصنف', 'النظام', 'العد', 'الفرق'], 'rows' => array_map(fn ($i) => [
115:             $i['sku'] ?? (string) $i['variant_id'],
116:             $i['system_qty'] !== null ? (string) $i['system_qty'] : '—',
117:             $i['counted_qty'] !== null ? (string) $i['counted_qty'] : '—',
118:             $i['difference'] !== null ? (string) $i['difference'] : '—',
119:         ], $items)]);
120:     }
121: }  1: <?php
