  7: use App\Models\StockTransfer;
  8: use App\Models\StockTransferItem;
  9: use App\Models\User;
 10: use App\Services\Ai\AgentTool;
 11: use App\Services\Ai\EntityResolver;
 12: use App\Services\Ai\Inventory\InventoryArgs;
 13: use App\Services\Ai\Inventory\InventoryPresenter;
