  5: namespace App\Services\Ai\Inventory\Tools;
  6: 
  7: use App\Enums\StockMovementType;
  8: use App\Models\StockMovement;
  9: use App\Models\User;
 10: use App\Services\Ai\AgentTool;
 11: use App\Services\Ai\EntityResolver;
 12: use App\Services\Ai\Inventory\InventoryArgs;
 13: use App\Services\Ai\Inventory\InventoryPresenter;
 14: use App\Services\Ai\ToolKind;
 15: use App\Services\Ai\ToolOutcome;
 16: use App\Services\BranchAccess;
 17: 
 18: final class ListMovementsTool implements AgentTool
 19: {
 20:     public function __construct(
 21:         private EntityResolver $resolver,
 22:         private BranchAccess $branches,
 23:         private InventoryPresenter $presenter,
 24:     ) {}
 25: 
 26:     public function name(): string
 27:     {
 28:         return 'list_movements';
 29:     }
 30: 
 31:     public function kind(): ToolKind
 32:     {
 33:         return ToolKind::Read;
 34:     }
 35: 
 36:     public function risk(): string
 37:     {
 38:         return 'low';
 39:     }
 40: 
 41:     public function permissions(): array
 42:     {
 43:         return ['inventory.view'];
 44:     }
 45: 
 46:     public function declaration(): array
 47:     {
 48:         return [
 49:             'name' => $this->name(),
 50:             'description' => 'دفتر حركات المخزون بفلاتر (نوع، فرع، متغير، مستخدم، فترة) مع cursor.',
 51:             'parameters' => [
 52:                 'type' => 'OBJECT',
 53:                 'properties' => (object) [
 54:                     'type' => ['type' => 'STRING', 'enum' => array_column(StockMovementType::cases(), 'value')],
 55:                     'variant_id' => ['type' => 'INTEGER'],
 56:                     'sku' => ['type' => 'STRING'],
 57:                     'query' => ['type' => 'STRING'],
 58:                     'branch_id' => ['type' => 'INTEGER'],
 59:                     'branch_query' => ['type' => 'STRING'],
 60:                     'user_id' => ['type' => 'INTEGER'],
 61:                     'from' => ['type' => 'STRING'],
 62:                     'to' => ['type' => 'STRING'],
 63:                     'cursor' => ['type' => 'INTEGER'],
 64:                     'limit' => ['type' => 'INTEGER'],
 65:                 ],
 66:             ],
 67:         ];
 68:     }
 69: 
 70:     public function handle(User $actor, array $args): ToolOutcome
 71:     {
 72:         $args = InventoryArgs::normalize($args);
 73:         $scope = InventoryArgs::scopeBranch($actor, $this->branches, $args);
 74:         if ($scope instanceof ToolOutcome) {
 75:             return $scope;
 76:         }
 77: 
 78:         $variantId = null;
 79:         if (! empty($args['variant_id']) || ! empty($args['sku']) || ! empty($args['query'])) {
 80:             $resolved = InventoryArgs::resolveVariant($actor, $this->resolver, $args);
 81:             if ($resolved instanceof ToolOutcome) {
 82:                 return $resolved;
 83:             }
 84:             $variantId = $resolved['variant']->id;
 85:         }
 86: 
 87:         $limit = min(50, max(1, (int) ($args['limit'] ?? 20)));
 88:         $movements = StockMovement::query()->with(['variant:id,sku', 'branch:id,name'])
 89:             ->when($scope['branch'] !== null, fn ($q) => $q->where('branch_id', $scope['branch']->id))
 90:             ->when($variantId !== null, fn ($q) => $q->where('product_variant_id', $variantId))
 91:             ->when($args['type'] ?? null, fn ($q, $v) => $q->where('type', $v))
 92:             ->when($args['user_id'] ?? null, fn ($q, $v) => $q->where('created_by', (int) $v))
 93:             ->when($args['from'] ?? null, fn ($q, $v) => $q->where('created_at', '>=', $v))
 94:             ->when($args['to'] ?? null, fn ($q, $v) => $q->where('created_at', '<=', $v))
 95:             ->when($args['cursor'] ?? null, fn ($q, $v) => $q->where('id', '<', (int) $v))
 96:             ->orderByDesc('id')->limit($limit + 1)->get();
 97: 
 98:         $hasMore = $movements->count() > $limit;
 99:         $items = $movements->take($limit)->map(fn (StockMovement $m) => [
100:             'id' => $m->id,
101:             'reference_number' => $m->reference_number,
102:             'variant_id' => $m->product_variant_id,
103:             'sku' => $m->variant?->sku,
104:             'branch_id' => $m->branch_id,
105:             'branch_name' => $m->branch?->name,
106:             'type' => $m->type->value,
107:             'affected_bucket' => $m->affected_bucket->value,
108:             'quantity' => (float) $m->quantity,
109:             'balance_before' => (float) $m->balance_before,
110:             'balance_after' => (float) $m->balance_after,
111:             'unit_cost' => $m->unit_cost !== null ? (float) $m->unit_cost : null,
112:             'created_by' => $m->created_by,
113:             'notes' => $m->notes !== null ? $this->presenter->untrusted($m->notes, 200) : null,
114:             'created_at' => $m->created_at?->toIso8601String(),
115:         ])->values()->all();
116: 
117:         $showCost = \App\Services\CostAccess::canView($actor);
118:         $table = array_map(fn ($i) => array_merge([
119:             (string) $i['id'], $i['reference_number'] ?? '—', $i['sku'] ?? '—',
120:             $i['type'], (string) $i['quantity'], (string) $i['balance_after'],
121:         ], $showCost ? [$i['unit_cost'] !== null ? (string) $i['unit_cost'] : '—'] : []), $items);
122:         $columns = ['#', 'المرجع', 'المتغير', 'النوع', 'الكمية', 'الرصيد بعد'];
123:         if ($showCost) {
124:             $columns[] = 'تكلفة الوحدة';
125:         }
126: 
127:         return $this->presenter->present($actor, [
128:             'movements' => $items,
129:             'next_cursor' => $hasMore ? end($items)['id'] ?? null : null,
130:             'has_more' => $hasMore,
131:         ], ['type' => 'table', 'columns' => $columns, 'rows' => $table]);
132:     }
133: } 1: <?php
