 76:             ->when($args['from_branch_id'] ?? null, fn ($q, $v) => $q->where('from_branch_id', (int) $v))
 77:             ->when($args['to_branch_id'] ?? null, fn ($q, $v) => $q->where('to_branch_id', (int) $v))
 78:             ->when($args['branch_id'] ?? null, fn ($q, $v) => $q->where(fn ($w) => $w->where('from_branch_id', (int) $v)->orWhere('to_branch_id', (int) $v)))
 79:             ->when($args['cursor'] ?? null, fn ($q, $v) => $q->where('id', '<', (int) $v))
 80:             ->orderByDesc('id')->limit($limit + 1)->get();
 81: 
 82:         $hasMore = $rows->count() > $limit;
 83:         $items = $rows->take($limit)->map(fn (StockTransfer $t) => [
 84:             'id' => $t->id,
 85:             'transfer_number' => $t->transfer_number,
 86:             'from_branch' => $t->fromBranch?->name,
 87:             'to_branch' => $t->toBranch?->name,
 88:             'status' => $t->status->value,
 89:             'items_count' => (int) ($t->items_count ?? 0),
 90:             'created_at' => $t->created_at?->toIso8601String(),
 91:             'deep_link' => '#/transfers/'.$t->id,
 92:         ])->values()->all();
 93: 
 94:         $table = array_map(fn ($i) => [
 95:             $i['transfer_number'], ($i['from_branch'] ?? '—').' ← '.($i['to_branch'] ?? '—'), $i['status'],
 96:         ], $items);
 97: 
 98:         return $this->presenter->present($actor, [
 99:             'transfers' => $items,
100:             'next_cursor' => $hasMore ? end($items)['id'] ?? null : null,
101:             'has_more' => $hasMore,
102:         ], ['type' => 'table', 'columns' => ['الرقم', 'المسار', 'الحالة'], 'rows' => $table]);
103:     }
104: }  1: <?php
