 17: final class ReceiveTransferTool extends TransferToolBase implements WriteTool, AgentTool
 18: {
 19:     public function name(): string
 20:     {
 21:         return 'receive_transfer';
 22:     }
 23: 
 24:     public function kind(): ToolKind
 25:     {
 26:         return ToolKind::Write;
 27:     }
 28: 
 29:     public function risk(): string
 30:     {
 31:         return 'medium';
 32:     }
 33: 
 34:     public function permissions(): array
 35:     {
 36:         return ['transfers.receive'];
 37:     }
 38: 
 39:     public function declaration(): array
 40:     {
 41:         return [
 42:             'name' => $this->name(),
 43:             'description' => 'استلام تحويل مشحون. الكمية لكل بند بين صفر والمشحون، والفرق يتسجل عجز تلقائيًا.',
 44:             'parameters' => [
 45:                 'type' => 'OBJECT',
 46:                 'properties' => (object) [
 47:                     'transfer_id' => ['type' => 'INTEGER'],
 48:                     'transfer_number' => ['type' => 'STRING'],
 49:                     'query' => ['type' => 'STRING'],
 50:                     'items' => ['type' => 'ARRAY', 'items' => [
 51:                         'type' => 'OBJECT',
 52:                         'required' => ['item_id', 'quantity'],
 53:                         'properties' => (object) [
 54:                             'item_id' => ['type' => 'INTEGER'],
 55:                             'quantity' => ['type' => 'NUMBER'],
 56:                         ],
 57:                     ]],
 58:                 ],
 59:             ],
 60:         ];
 61:     }
 62: 
 63:     public function prepare(User $actor, array $args): ToolOutcome
 64:     {
 65:         $args = InventoryArgs::normalize($args);
 66:         $resolved = $this->resolveTransfer($actor, $args);
 67:         if ($resolved instanceof ToolOutcome) {
 68:             return $resolved;
 69:         }
 70:         $transfer = $resolved['transfer'];
 71:         if ($transfer->status !== TransferStatus::Shipped) {
 72:             return ToolOutcome::denied('الاستلام من المشحون بس (الحالة: '.$transfer->status->value.').', auditable: false);
 73:         }
 74:         $payload = $this->itemsPayload($transfer, $args['items'] ?? null, 'shipped_qty');
 75:         if ($payload instanceof ToolOutcome) {
 76:             return $payload;
 77:         }
 78: 
 79:         $warnings = [];
 80:         foreach ($transfer->items as $item) {
 81:             $received = $payload[$item->id] ?? (float) $item->shipped_qty;
 82:             $gap = round((float) $item->shipped_qty - $received, 4);
 83:             if ($gap > 0) {
 84:                 $warnings[] = "عجز {$gap} في البند {$item->id} ({$item->variant?->sku}) — هيتسجل تلقائيًا.";
 85:             }
 86:         }
 87: 
 88:         return $this->proposals->make(
 89:             $actor,
 90:             $this->name(),
 91:             ['transfer_id' => $transfer->id, 'items' => array_map(fn ($id, $q) => ['item_id' => $id, 'quantity' => $q], array_keys($payload), $payload)],
 92:             risk: $this->risk(),
 93:             title: "استلام {$transfer->transfer_number}",
 94:             before: ['status' => TransferStatus::Shipped->value] + $this->itemsView($transfer),
 95:             after: ['status' => TransferStatus::Received->value, 'received' => $payload],
 96:             warnings: $warnings,
 97:             expectedVersions: [$this->versionKey($transfer) => $transfer->version],
 98:             extraPreview: ['block_type' => 'transfer_timeline'] + $this->timeline($transfer),
 99:         );
100:     }
101: 
102:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
103:     {
104:         $a = $action->args;
105:         $transfer = StockTransfer::findOrFail((int) $a['transfer_id']);
106:         $payload = [];
107:         foreach ($a['items'] as $item) {
108:             $payload[(int) $item['item_id']] = $item['quantity'];
109:         }
110:         $updated = $this->transfers->receive($transfer, $payload, $actor->id, null, (int) ($action->expected_versions[$this->versionKey($transfer)] ?? 0));
111: 
112:         return ToolOutcome::result(true, "اتستلم {$updated->transfer_number}.", [
113:             'transfer_id' => $updated->id,
114:             'transfer_number' => $updated->transfer_number,
115:             'deep_link' => '#/transfers/'.$updated->id,
116:         ]);
117:     }
