 74:         if ($resolved instanceof ToolOutcome) {
 75:             return $resolved;
 76:         }
 77:         $transfer = $resolved['transfer'];
 78:         if ($transfer->status !== TransferStatus::Draft) {
 79:             return ToolOutcome::denied('التعديل متاح على المسودة بس (الحالة: '.$transfer->status->value.').', auditable: false);
 80:         }
 81: 
 82:         $data = [];
 83:         if (isset($args['from_branch_id'])) {
 84:             $data['from_branch_id'] = (int) $args['from_branch_id'];
 85:         }
 86:         if (isset($args['to_branch_id'])) {
 87:             $data['to_branch_id'] = (int) $args['to_branch_id'];
 88:         }
 89:         if (array_key_exists('notes', $args)) {
 90:             $data['notes'] = $args['notes'];
 91:         }
 92:         if (array_key_exists('items', $args)) {
 93:             $items = $this->draftItems($actor, $args['items']);
 94:             if ($items instanceof ToolOutcome) {
 95:                 return $items;
 96:             }
 97:             $data['items'] = array_map(fn ($i) => [
 98:                 'product_variant_id' => $i['product_variant_id'],
 99:                 'requested_qty' => $i['quantity'],
100:                 'from_location_id' => $i['from_location_id'],
101:                 'to_location_id' => $i['to_location_id'],
102:             ], $items);
103:         }
104:         if ($data === []) {
105:             return ToolOutcome::denied('مفيش حاجة تتعدل.', auditable: false);
106:         }
107: 
108:         return $this->proposals->make(
109:             $actor,
110:             $this->name(),
111:             array_merge(['transfer_id' => $transfer->id], $data),
112:             risk: $this->risk(),
113:             title: "تعديل مسودة {$transfer->transfer_number}",
114:             before: ['status' => $transfer->status->value] + $this->itemsView($transfer),
115:             after: ['status' => TransferStatus::Draft->value] + (isset($data['items']) ? ['items' => $data['items']] : $this->itemsView($transfer)),
116:             expectedVersions: [$this->versionKey($transfer) => $transfer->version],
117:             extraPreview: ['block_type' => 'transfer_timeline'] + $this->timeline($transfer->fresh()),
118:         );
119:     }
120: 
121:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
122:     {
123:         $a = $action->args;
124:         $transfer = \App\Models\StockTransfer::findOrFail((int) $a['transfer_id']);
125:         $data = array_intersect_key($a, array_flip(['from_branch_id', 'to_branch_id', 'notes', 'items']));
126:         unset($data['transfer_id']);
127:         $updated = $this->transfers->update($transfer, $data, $actor->id);
