129:         return ToolOutcome::result(true, "اتعدلت مسودة {$updated->transfer_number}.", [
130:             'transfer_id' => $updated->id,
131:             'transfer_number' => $updated->transfer_number,
132:             'deep_link' => '#/transfers/'.$updated->id,
133:         ]);
134:     }
