 18: final class WhatIfTransferCoverageTool implements AgentTool
 19: {
 20:     public function __construct(
 21:         private EntityResolver $resolver,
 22:         private BranchAccess $branches,
 23:         private InventoryPresenter $presenter,
 24:     ) {}
 25: 
 26:     public function name(): string
 27:     {
 28:         return 'what_if_transfer_coverage';
 29:     }
 30: 
 31:     public function kind(): ToolKind
 32:     {
 33:         return ToolKind::Read;
 34:     }
 35: 
 36:     public function risk(): string
 37:     {
 38:         return 'low';
 39:     }
 40: 
 41:     public function permissions(): array
 42:     {
 43:         return ['inventory.view'];
 44:     }
 45: 
 46:     public function declaration(): array
 47:     {
 48:         return [
 49:             'name' => $this->name(),
 50:             'description' => 'يحسب تغطية الفرع قبل وبعد نقل افتراضي — من غير ما يكتب حاجة.',
 51:             'parameters' => [
 52:                 'type' => 'OBJECT',
 53:                 'required' => ['quantity', 'from_branch_id'],
 54:                 'properties' => (object) [
 55:                     'variant_id' => ['type' => 'INTEGER'],
 56:                     'sku' => ['type' => 'STRING'],
 57:                     'barcode' => ['type' => 'STRING'],
 58:                     'query' => ['type' => 'STRING'],
 59:                     'quantity' => ['type' => 'INTEGER'],
 60:                     'from_branch_id' => ['type' => 'INTEGER'],
 61:                     'to_branch_id' => ['type' => 'INTEGER'],
 62:                 ],
 63:             ],
 64:         ];
 65:     }
 66: 
 67:     public function handle(User $actor, array $args): ToolOutcome
 68:     {
 69:         $args = InventoryArgs::normalize($args);
 70:         $resolved = InventoryArgs::resolveVariant($actor, $this->resolver, $args);
 71:         if ($resolved instanceof ToolOutcome) {
 72:             return $resolved;
 73:         }
 74:         try {
 75:             DiscreteQuantity::assert($args['quantity'] ?? null);
 76:         } catch (\App\Exceptions\BusinessException $e) {
 77:             return ToolOutcome::denied($e->getMessage(), auditable: false);
 78:         }
 79:         $variant = $resolved['variant'];
 80:         $qty = (float) $args['quantity'];
 81:         $from = (int) ($args['from_branch_id'] ?? 0);
 82:         $to = isset($args['to_branch_id']) ? (int) $args['to_branch_id'] : null;
 83:         if ($from < 1) {
 84:             return ToolOutcome::denied('حدد فرع الإرسال.', auditable: false);
 85:         }
 86:         try {
 87:             $restricted = $this->branches->restrictedBranch($actor);
 88:         } catch (\Throwable) {
 89:             return ToolOutcome::denied('النطاق غير مسموح.', auditable: false);
 90:         }
 91:         if ($restricted !== null && $from !== $restricted && $to !== $restricted) {
 92:             return ToolOutcome::denied('الفرع خارج نطاقك.', auditable: false);
 93:         }
 94: 
 95:         $donorBefore = InventoryCoverage::coverageDays($variant->id, $from);
 96:         $donorAvail = InventoryCoverage::available($variant->id, $from);
 97:         $donorDaily = InventoryCoverage::avgDailySale($variant->id, $from);
 98:         $donorAfter = $donorDaily > 0 ? round(max(0.0, $donorAvail - $qty) / $donorDaily, 1) : null;
 99: 
100:         $data = [
101:             'variant' => ['id' => $variant->id, 'sku' => $variant->sku],
102:             'quantity' => $qty,
103:             'donor_branch_id' => $from,
104:             'donor_available' => $donorAvail,
105:             'donor_coverage_before' => $donorBefore,
106:             'donor_coverage_after' => $donorAfter,
107:             'verdict' => $qty > $donorAvail
108:                 ? 'الكمية أكبر من المتاح في فرع الإرسال.'
109:                 : ($donorAfter !== null && $donorAfter < 7 ? 'النقل ده هيخلّي فرع الإرسال مهدد بالنفاد.' : 'النقل آمن على فرع الإرسال.'),
110:         ];
111:         if ($to !== null) {
112:             $destBefore = InventoryCoverage::coverageDays($variant->id, $to);
113:             $data['dest_branch_id'] = $to;
114:             $data['dest_coverage_before'] = $destBefore;
115:         }
116: 
117:         return $this->presenter->present($actor, $data);
118:     }
119: }  1: <?php
