 24: final class EntityResolver
 25: {
 26:     public function __construct(private BranchAccess $branches) {}
 27: 
 28:     public static function normalizeDigits(string $value): string
 29:     {
 30:         return strtr($value, [
 31:             '٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4',
 32:             '٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9',
 33:             '۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4',
 34:             '۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9',
 35:         ]);
 36:     }
 37: 
 38:     /** @return list<string> */
 39:     public static function expandCatalogSearchTerms(string $query): array
 40:     {
 41:         $clean = trim(self::normalizeDigits($query));
 42:         if ($clean === '') {
 43:             return [];
 44:         }
 45:         $terms = [$clean];
 46:         $norm = self::normalizeForSearch($clean);
 47:         if ($norm !== '' && $norm !== $clean) {
 48:             $terms[] = $norm;
 49:         }
 50:         $synonyms = (array) config('ai_catalog_synonyms', []);
 51:         foreach ($synonyms as $phrase => $expansions) {
 52:             $normPhrase = self::normalizeForSearch((string) $phrase);
 53:             if ($normPhrase !== '' && (str_contains($norm, $normPhrase) || str_contains(mb_strtolower($clean), mb_strtolower((string) $phrase)))) {
 54:                 foreach ((array) $expansions as $exp) {
 55:                     $terms[] = (string) $exp;
 56:                 }
 57:             }
 58:         }
 59: 
 60:         return array_values(array_unique(array_filter($terms, fn ($t) => trim($t) !== '')));
 61:     }
 62: 
 63:     public static function normalize(string $value): string
 64:     {
 65:         $v = mb_strtolower(trim($value));
 66:         $v = str_replace(['أ', 'إ', 'آ', 'ٱ'], 'ا', $v);
 67:         $v = str_replace(['ة'], 'ه', $v);
 68:         $v = str_replace(['ى'], 'ي', $v);
 69:         $v = preg_replace('/[\x{064B}-\x{065F}\x{0640}]/u', '', $v) ?? $v;
 70: 
 71:         return preg_replace('/\s+/u', ' ', $v) ?? $v;
 72:     }
 73: 
 74:     private function restricted(?User $actor): ?int
 75:     {
 76:         if (! $actor) {
 77:             return null;
 78:         }
 79:         try {
 80:             return $this->branches->restrictedBranch($actor);
 81:         } catch (\Throwable) {
 82:             return -1;
 83:         }
 84:     }
 85: 
 86:     /** @return list<array{id:int,label:string,meta:string}> */
 87:     public function branches(User $actor, string $query = '', array $filters = []): array
 88:     {
 89:         $restricted = $this->restricted($actor);
 90:         if ($restricted === -1) {
 91:             return [];
 92:         }
 93: 
 94:         // M6/L5: الفلترة في SQL (ILIKE محمي بـ SearchTerm::escape) مع LIMIT —
 95:         // استعلام بلا نتيجة ما يمسحش الجدول كله ولا يعمل ذاكرة lazy.
 96:         return Branch::query()->withCount('users')
 97:             ->when($restricted !== null, fn ($x) => $x->whereKey($restricted))
 98:             ->when(array_key_exists('active', $filters), fn ($x) => $x->where('is_active', $filters['active']))
 99:             ->when(isset($filters['type']), fn ($x) => $x->where('type', $filters['type']))
100:             ->when(isset($filters['city']), fn ($x) => $x->where('city', $filters['city']))
101:             ->when($query !== '', fn ($x) => $x->where(fn ($w) => $w
102:                 ->where('name', 'ilike', SearchTerm::pattern($query))
103:                 ->orWhere('code', 'ilike', SearchTerm::pattern($query))
104:                 ->orWhere('city', 'ilike', SearchTerm::pattern($query))))
105:             ->orderBy('id')
106:             ->limit(50)
107:             ->get()
108:             ->map(fn (Branch $b) => ['id' => $b->id, 'label' => $b->name.' ('.$b->code.')', 'meta' => trim(($b->city ?? '').' · '.($b->is_active ? 'نشط' : 'متوقف').' · موظفين: '.$b->users_count)])
109:             ->values()
110:             ->all();
111:     }
