149:     /** @return list<array{id:int,label:string,meta:string}> */
150:     public function locations(User $actor, string $query = '', ?int $branchId = null): array
151:     {
152:         $restricted = $this->restricted($actor);
153:         if ($restricted === -1) {
154:             return [];
155:         }
156:         $cleanCode = trim(self::normalizeDigits($query));
157:         // مسار سريع: كود موقع مضبوط (A-03-2).
158:         if ($cleanCode !== '' && ! preg_match('/\s/u', $cleanCode)) {
159:             $exact = Location::query()
160:                 ->when($restricted !== null, fn ($q) => $q->where('branch_id', $restricted), fn ($q) => $q->when($branchId !== null, fn ($w) => $w->where('branch_id', $branchId)))
161:                 ->whereRaw('LOWER(code) = LOWER(?)', [$cleanCode])->limit(2)->get();
162:             if ($exact->count() === 1) {
163:                 $l = $exact->first();
164: 
165:                 return [[
166:                     'id' => $l->id,
167:                     'label' => $l->name.' ('.$l->code.')',
168:                     'meta' => trim(($l->type?->value ?? '').' · '.($l->is_active ? 'نشط' : 'معطّل').' · فرع: '.$l->branch_id),
169:                 ]];
170:             }
171:         }
172: 
173:         // M1: قيد الفرع يطبق أولًا — مقيّد بفرع ما يقدرش يوجّه branch_id لفرع تاني.
174:         // M6/L5: نفس الفلترة السلكية المحمية مع LIMIT.
175:         return Location::query()
176:             ->when($restricted !== null, fn ($q) => $q->where('branch_id', $restricted), fn ($q) => $q->when($branchId !== null, fn ($w) => $w->where('branch_id', $branchId)))
177:             ->when($query !== '', fn ($x) => $x->where(fn ($w) => $w
178:                 ->where('name', 'ilike', SearchTerm::pattern($query))
179:                 ->orWhere('code', 'ilike', SearchTerm::pattern($query))))
180:             ->orderBy('id')
181:             ->limit(50)
182:             ->get()
183:             ->map(fn (Location $l) => [
184:                 'id' => $l->id,
185:                 'label' => $l->name.' ('.$l->code.')',
186:                 'meta' => trim(($l->type?->value ?? '').' · '.($l->is_active ? 'نشط' : 'معطّل').' · فرع: '.$l->branch_id),
187:             ])
188:             ->values()
189:             ->all();
190:     }
