192:     /** @return list<array{id:int,label:string,meta:string}> */
193:     public function transfers(User $actor, string $query = '', array $filters = []): array
194:     {
195:         $restricted = $this->restricted($actor);
196:         if ($restricted === -1) {
197:             return [];
198:         }
199:         $scope = fn ($x) => $restricted !== null
200:             ? $x->where(fn ($w) => $w->where('from_branch_id', $restricted)->orWhere('to_branch_id', $restricted))
201:             : $x;
202:         $clean = trim(self::normalizeDigits($query));
203: 
204:         // مسار سريع: رقم مستند مضبوط (TRF-00012).
205:         if ($clean !== '' && preg_match('/^[A-Za-z]+-\d+$/', $clean)) {
206:             $exact = StockTransfer::query()->with(['fromBranch:id,name', 'toBranch:id,name'])
207:                 ->tap($scope)->whereRaw('LOWER(transfer_number) = LOWER(?)', [$clean])->limit(2)->get();
208:             if ($exact->count() === 1) {
209:                 return $this->mapTransfers($exact)->all();
210:             }
211:         }
212: 
213:         return $this->mapTransfers(StockTransfer::query()->with(['fromBranch:id,name', 'toBranch:id,name'])
214:             ->tap($scope)
215:             ->when(isset($filters['status']), fn ($x) => $x->where('status', $filters['status']))
216:             ->when(self::mentionsYesterday($clean), fn ($x) => $x->whereDate('created_at', today()->subDay()))
217:             ->when(self::mentionsToday($clean), fn ($x) => $x->whereDate('created_at', today()))
218:             ->when($clean !== '', function ($x) use ($clean): void {
219:                 $pattern = SearchTerm::pattern($clean);
220:                 $x->where(fn ($w) => $w
221:                     ->where('transfer_number', 'ilike', $pattern)
222:                     ->orWhere('notes', 'ilike', $pattern)
223:                     ->orWhereHas('fromBranch', fn ($b) => $b->where('name', 'ilike', $pattern))
224:                     ->orWhereHas('toBranch', fn ($b) => $b->where('name', 'ilike', $pattern)));
225:             })
226:             ->orderByDesc('id')
227:             ->limit(20)
228:             ->get())->all();
229:     }
