337:     /** تقنيع رقم موبايل: 11 رقمًا يظهر أول 3 وآخر 3 فقط، غير كده ***. */
338:     public static function maskPhone(?string $p): string
339:     {
340:         return $p && strlen($p) === 11 ? substr($p, 0, 3).'*****'.substr($p, -3) : '***';
341:     }
342: 
343:     /** تقنيع رقم ضريبي/سجل تجاري: أول حرفين وآخر حرفين فقط. */
344:     public static function maskLegal(?string $v): ?string
345:     {
346:         if ($v === null || trim($v) === '') {
347:             return null;
348:         }
349:         $v = trim($v);
350: 
351:         return mb_strlen($v) <= 4 ? '***' : mb_substr($v, 0, 2).'***'.mb_substr($v, -2);
352:     }
