427:     /** @param list<string> $fields */
428:     public function matches(string $query, array $fields): bool
429:     {
430:         $nq = self::normalizeForSearch($query);
431:         if ($nq === '') {
432:             return true;
433:         }
434:         foreach ($fields as $f) {
435:             if (str_contains(self::normalizeForSearch($f), $nq)) {
436:                 return true;
437:             }
438:         }
439: 
440:         return false;
441:     }
442: 
443:     public static function normalizeForSearch(string $value): string
444:     {
445:         return preg_replace('/(^|\s)ال/u', '$1', self::normalize($value)) ?? self::normalize($value);
446:     }
