459:     public function categories(User $actor, string $q = '', array $filters = []): array
460:     {
461:         $clean = trim(self::normalizeDigits($q));
462:         $terms = self::expandCatalogSearchTerms($clean);
463: 
464:         return Category::query()
465:             ->with('parent:id,name_ar,name_en')
466:             ->withCount('products')
467:             ->when(array_key_exists('active', $filters), fn ($x) => $x->where('is_active', (bool) $filters['active']))
468:             ->when(array_key_exists('parent_id', $filters), fn ($x) => $filters['parent_id'] === null ? $x->whereNull('parent_id') : $x->where('parent_id', (int) $filters['parent_id']))
469:             ->when(! empty($filters['root_only']), fn ($x) => $x->whereNull('parent_id'))
470:             ->when($terms !== [], function ($x) use ($terms): void {
471:                 $x->where(function ($w) use ($terms): void {
472:                     foreach ($terms as $term) {
473:                         $pattern = SearchTerm::pattern($term);
474:                         $w->orWhereLike('name_ar', $pattern, caseSensitive: false)
475:                             ->orWhereLike('name_en', $pattern, caseSensitive: false)
476:                             ->orWhereLike('slug', $pattern, caseSensitive: false);
477:                     }
478:                 });
479:             })
480:             ->orderBy('sort_order')
481:             ->orderBy('id')
482:             ->limit(20)
483:             ->get()
484:             ->map(fn (Category $c) => [
485:                 'id' => $c->id,
486:                 'label' => $c->name_ar.' ('.$c->slug.')',
487:                 'meta' => ($c->is_active ? 'نشط' : 'معطّل').' · '.$c->products_count.' منتج'.($c->parent ? ' · أب: '.$c->parent->name_ar : ''),
488:             ])
489:             ->values()
490:             ->all();
491:     }
