493:     /** @return list<array{id:int,label:string,meta:string}> */
494:     public function products(User $actor, string $q = '', array $filters = []): array
495:     {
496:         $clean = trim(self::normalizeDigits($q));
497: 
498:         // أي query من غير مسافات وطوله 4 أو أكتر يتجرب الأول كـ SKU/barcode/code مضبوط (LOWER(sku) = LOWER(?)). لو لقى نتيجة واحدة يرجعها على طول.
499:         if ($clean !== '' && ! preg_match('/\s/u', $clean) && mb_strlen($clean) >= 4) {
500:             $exact = Product::query()
501:                 ->with('category:id,name_ar,name_en')
502:                 ->withCount('variants')
503:                 ->where(function ($w) use ($clean): void {
504:                     $w->whereRaw('LOWER(code) = LOWER(?)', [$clean])
505:                         ->orWhereIn('products.id', ProductVariant::query()->select('product_id')
506:                             ->where(fn ($v) => $v->whereRaw('LOWER(sku) = LOWER(?)', [$clean])->orWhereRaw('LOWER(barcode) = LOWER(?)', [$clean])));
507:                 })
508:                 ->limit(2)
509:                 ->get();
510:             if ($exact->count() === 1) {
511:                 $p = $exact->first();
512: 
513:                 return [[
514:                     'id' => $p->id,
515:                     'label' => $p->name_ar.' — '.$p->code,
516:                     'meta' => $p->status->value.' · '.$p->variants_count.' متغير · '.($p->category?->name_ar ?? '—'),
517:                 ]];
518:             }
519:         }
520: 
521:         $terms = self::expandCatalogSearchTerms($clean);
522:         $query = Product::query()
523:             ->with('category:id,name_ar,name_en')
524:             ->withCount('variants')
525:             ->when(isset($filters['status']), fn ($x) => $x->where('status', $filters['status']))
526:             ->when(isset($filters['category_id']), function ($x) use ($filters): void {
527:                 $cat = Category::find((int) $filters['category_id']);
528:                 if ($cat) {
529:                     $ids = ! empty($filters['include_children']) ? [$cat->id, ...$cat->descendantIds()] : [$cat->id];
530:                     $x->whereIn('category_id', $ids);
531:                 } else {
532:                     $x->where('category_id', (int) $filters['category_id']);
533:                 }
534:             })
535:             ->when(isset($filters['sales_channel']), fn ($x) => $x->where('sales_channel', $filters['sales_channel']))
536:             ->when(($filters['missing'] ?? null) === 'images', function ($x): void {
537:                 $x->whereDoesntHave('media', fn ($m) => $m->where('collection_name', 'images'))
538:                     ->whereDoesntHave('variants', fn ($v) => $v->where('is_active', true)->whereHas('media', fn ($m) => $m->where('collection_name', 'images')));
539:             })
540:             ->when(($filters['missing'] ?? null) === 'prices', function ($x): void {
541:                 $x->whereHas('variants', function ($v): void {
542:                     $v->where('is_active', true)->where(function ($p): void {
543:                         $p->where(fn ($r) => $r->whereIn('products.sales_channel', ['retail', 'both'])->where(fn ($w) => $w->whereNull('retail_price')->orWhere('retail_price', '<=', 0)))
544:                             ->orWhere(fn ($r) => $r->whereIn('products.sales_channel', ['wholesale', 'both'])->where(fn ($w) => $w->whereNull('wholesale_price')->orWhere('wholesale_price', '<=', 0)));
545:                     });
546:                 });
547:             });
548: 
549:         if ($terms !== []) {
550:             $query->where(function ($w) use ($terms, $clean): void {
551:                 $w->whereRaw('LOWER(code) = LOWER(?)', [$clean])
552:                     ->orWhereIn('products.id', ProductVariant::query()->select('product_id')
553:                         ->where(fn ($v) => $v->whereRaw('LOWER(sku) = LOWER(?)', [$clean])->orWhereRaw('LOWER(barcode) = LOWER(?)', [$clean])));
