 30:     public function confirm(User $actor, AiPendingAction $action, ?string $typed = null, ?array $selectedItems = null): ToolOutcome
 31:     {
 32:         if ($action->tool === 'bulk_actions') {
 33:             return $this->confirmBulk($actor, $action, $typed, $selectedItems);
 34:         }
 35:         $toolInstance = $this->registry->toolInstance($action->tool);
 36:         if ($toolInstance instanceof \App\Services\Ai\Contracts\ExecutesOutsideTransaction) {
 37:             return $this->confirmOutsideTransaction($actor, $action, $typed, $toolInstance);
 38:         }
 39:         try {
 40:             $result = DB::transaction(function () use ($actor, $action, $typed) {
 41:                 $this->lockForAction($action->tool);
 42:                 $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
 43:                 try {
 44:                     return $this->confirmLocked($actor, $locked, $typed);
 45:                 } catch (HttpExceptionInterface $e) {
 46:                     return $e;
 47:                 }
 48:             });
 49:         } catch (\Throwable $e) {
 50:             // M-3: unexpected errors must not leave the proposal stuck in
 51:             // pending — record the failure outside the rolled-back transaction.
 52:             if (! $e instanceof HttpExceptionInterface) {
 53:                 AiPendingAction::whereKey($action->id)->where('status', 'pending')
 54:                     ->update(['status' => 'failed', 'result' => ['message' => 'تعذّر التنفيذ بسبب خطأ غير متوقع؛ اطلب اقتراحًا جديدًا.']]);
 55:             }
 56:             throw $e;
 57:         }
 58:         if ($result instanceof \Throwable) {
 59:             throw $result;
 60:         }
 61: 
 62:         return $result;
 63:     }
