 65:     private function confirmOutsideTransaction(User $actor, AiPendingAction $action, ?string $typed, WriteTool $tool): ToolOutcome
 66:     {
 67:         $claim = DB::transaction(function () use ($actor, $action, $typed) {
 68:             $this->lockForAction($action->tool);
 69:             $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
 70:             try {
 71:                 return $this->confirmLocked($actor, $locked, $typed);
 72:             } catch (HttpExceptionInterface $e) {
 73:                 return $e;
 74:             }
 75:         });
 76:         if ($claim instanceof \Throwable) {
 77:             throw $claim;
 78:         }
 79:         if ($claim instanceof ToolOutcome && $claim->type !== 'claimed') {
 80:             return $claim;
 81:         }
 82: 
 83:         try {
 84:             $outcome = $tool->execute($actor, $action->fresh() ?? $action);
 85:         } catch (\Throwable $e) {
 86:             DB::transaction(function () use ($action, $e): void {
 87:                 $locked = AiPendingAction::query()->lockForUpdate()->find($action->id);
 88:                 if ($locked && $locked->status === 'confirmed') {
 89:                     $message = ($e instanceof BusinessException || $e instanceof ValidationException)
 90:                         ? ($e instanceof ValidationException ? collect($e->errors())->flatten()->implode(' ') : $e->getMessage())
 91:                         : 'تعذّر التنفيذ؛ راجع البيانات أو اطلب اقتراحًا جديدًا.';
 92:                     $this->markFailed($locked, $message ?: 'تعذّر التنفيذ؛ راجع البيانات أو اطلب اقتراحًا جديدًا.');
 93:                 }
 94:             });
 95:             if ($e instanceof BusinessException && $e->status === 409) {
 96:                 abort(409, $e->getMessage());
 97:             }
 98:             if ($e instanceof HttpExceptionInterface) {
 99:                 throw $e;
100:             }
101:             if ($e instanceof BusinessException || $e instanceof ValidationException) {
102:                 $msg = $e instanceof ValidationException ? collect($e->errors())->flatten()->implode(' ') : $e->getMessage();
103: 
104:                 return ToolOutcome::result(false, $msg ?: 'تعذّر التنفيذ.');
105:             }
106:             throw $e;
107:         }
108: 
109:         return DB::transaction(function () use ($action, $outcome): ToolOutcome {
110:             $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
111:             if ($locked->status === 'confirmed') {
112:                 return $this->finalizeAction($locked, $outcome);
113:             }
114: 
115:             return ToolOutcome::wrap($outcome->type, $outcome->data, $outcome->uiBlock, $outcome->message);
116:         });
117:     }
