119:     private function confirmBulk(User $actor, AiPendingAction $action, ?string $typed, ?array $selectedItems): ToolOutcome
120:     {
121:         $claim = DB::transaction(function () use ($actor, $action, $typed, $selectedItems) {
122:             StaffAdministration::lock();
123:             $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
124:             abort_unless($locked->user_id === $actor->id, 403);
125:             $this->authorizeTool($actor, $locked);
126:             if ($locked->status === 'executed') {
127:                 return ToolOutcome::result((bool) ($locked->result['ok'] ?? false), $locked->result['message'], $locked->result);
128:             }
129:             abort_unless($locked->status === 'pending' && $locked->expires_at->isFuture(), 409, 'العملية الجماعية مش متاحة للتنفيذ.');
130:             abort_unless(trim((string) $typed) === 'تنفيذ', 422, 'اكتب تنفيذ لتأكيد المجموعة.');
131:             $ids = $locked->args['action_ids'];
132:             $selected = $selectedItems ?? $ids;
133:             abort_if(! $selected || array_diff($selected, $ids) !== [] || count(array_unique($selected)) !== count($selected), 422);
134:             $locked->forceFill(['status' => 'confirmed'])->save();
135:             // M-4: المختارون فقط يتحولون لـ pending، والباقون يُلغون في نفس
136:             // الـ transaction — فلا نافذة سباق لتأكيد مستبعد من تبويب آخر،
137:             // ولا أيتام pending لو انهارت العملية بعد الـ claim.
138:             AiPendingAction::query()->whereIn('id', $selected)->where('status', 'bulk_child')->update(['status' => 'pending']);
139:             AiPendingAction::query()->whereIn('id', array_diff($ids, $selected))->whereIn('status', ['bulk_child', 'pending'])->update(['status' => 'cancelled']);
140: 
141:             return ['selected' => $selected, 'all' => $ids];
142:         });
143:         if ($claim instanceof ToolOutcome) {
144:             return $claim;
145:         }
146:         $results = [];
147:         foreach ($claim['selected'] as $id) {
148:             $child = AiPendingAction::query()->where('conversation_id', $action->conversation_id)->where('user_id', $actor->id)->findOrFail($id);
149:             try {
150:                 // M-5: set_branch_status خرج من الـ bulk نهائيًا (كان نص
151:                 // "تنفيذ" واحد يؤكد تعطيل فروع، والحماية بالكود المكتوب
152:                 // تُلغى من السيرفر بتعبئة تلقائية — residual risk M10).
153:                 // لا تعبئة تلقائية لأي نص تأكيد هنا: أي عنصر عالي الخطورة
154:                 // في مجموعة قديمة بلا نص مدخل من المستخدم يفشل برسالة
155:                 // واضحة بدل تنفيذه بتعبئة من السيرفر.
156:                 $outcome = $this->confirm($actor, $child, null);
157:                 $results[] = ['action_id' => $id, 'ok' => $outcome->type === 'result', 'message' => $outcome->message];
158:             } catch (QueryException $e) {
159:                 if (! $this->isRetryableLockFailure($e)) {
160:                     report($e);
161:                     AiPendingAction::whereKey($id)->where('status', 'pending')->update(['status' => 'failed']);
162:                     $results[] = ['action_id' => $id, 'ok' => false, 'message' => 'تعذّر تنفيذ العنصر ده ضمن الدفعة؛ راجع التفاصيل أو جرّبه لوحده.'];
163: 
164:                     continue;
165:                 }
166:                 $this->retryBulkConflict($action, $claim, $results);
167:             } catch (RetryableConflict $e) {
168:                 // H2: قفل/تايم-أوت من confirmLocked أو StaffAdministration::lock
169:                 // يصل هنا كاستثناء مخصص — نفس مسار إعادة المحاولة، لا failed.
170:                 $this->retryBulkConflict($action, $claim, $results);
171:             } catch (\Throwable $e) {
172:                 if (! $e instanceof HttpExceptionInterface && ! $e instanceof ValidationException) {
173:                     report($e);
174:                 }
175:                 AiPendingAction::whereKey($id)->where('status', 'pending')->update(['status' => 'failed']);
176:                 $results[] = ['action_id' => $id, 'ok' => false, 'message' => 'تعذّر تنفيذ العنصر ده ضمن الدفعة؛ راجع التفاصيل أو جرّبه لوحده.'];
177:             }
178:         }
179:         $successes = count(array_filter($results, fn ($item) => $item['ok']));
180:         $ok = $successes === count($results);
181:         $message = 'تم تنفيذ '.$successes.' من '.count($results).' عمليات.';
182:         // L4: الأب الفاشل كليًا يُوسم failed لا executed — وإلا usage()
183:         // والتقارير تحسبه نجاحًا.
184:         $parentStatus = $successes === 0 ? 'failed' : 'executed';
185:         $action->refresh()->forceFill(['status' => $parentStatus, 'executed_at' => now(), 'result' => ['ok' => $ok, 'message' => $message, 'items' => $results]])->save();
186:         $block = ['type' => 'result', 'ok' => $ok, 'message' => $message, 'items' => $results];
187:         $this->event($action, 'result', $message, [$block]);
188: 
189:         return ToolOutcome::result($ok, $message, ['items' => $results], $block);
190:     }
