192:     /**
193:      * H2: تعارض مؤقت أثناء تأكيد عنصر جماعي — الأب يرجع pending
194:      * (قابل للتأكيد من جديد)، والعنصر الحالي يبقى pending، ولا شيء يوسم
195:      * failed. تُرمى 409 دائمًا بعد تسجيل حدث النتيجة.
196:      *
197:      * @param  array{selected:list<string>,all:list<string>}  $claim
198:      * @param  list<array{action_id:string,ok:bool,message:string}>  $results
199:      */
200:     private function retryBulkConflict(AiPendingAction $action, array $claim, array $results): never
201:     {
202:         AiPendingAction::whereKey($action->id)->where('status', 'confirmed')->update(['status' => 'pending']);
203:         $done = count(array_filter($results, fn ($item) => $item['ok']));
204:         $message = $done === 0
205:             ? 'السجل مشغول بتعديل تاني؛ مفيش حاجة اتنفذت. جرّب تأكيد الدفعة تاني بعد لحظة.'
206:             : 'السجل مشغول بتعديل تاني؛ العناصر المنفذة: '.$done.' من '.count($claim['selected']).'. الباقي ما اتنفذش — جرّب تأكيد الدفعة تاني بعد لحظة.';
207:         $this->event($action, 'result', $message, [['type' => 'result', 'ok' => false, 'message' => $message]]);
208:         abort(409, $message);
209:     }
