211:     /**
212:      * M7: القفل الاستشاري العام لأدوات إدارة الموظفين فقط. أدوات
213:      * الكتالوج والمخزون تعتمد على أقفالها الخاصة (CatalogLock::tree +
214:      * أقفال الصفوف، أو InventoryService::lockLevels بترتيب ثابت)، فأخذ
215:      * القفل العام عند تأكيدها كان يسلسل كل شيء خلف أثقل عملية.
216:      */
217:     private function lockForAction(string $tool): void
218:     {
219:         $def = $this->registry->definitions()[$tool] ?? null;
220:         $provider = $def['provider'] ?? null;
221:         if ($provider instanceof \App\Services\Ai\Contracts\ToolProvider && ! $provider->usesGlobalAdminLock()) {
222:             return;
223:         }
224:         StaffAdministration::lock();
225:     }
