227:     private function authorizeTool(User $actor, AiPendingAction $action): void
228:     {
229:         $actor->refresh();
230:         abort_unless($this->settings->getBool('ai_enabled', false), 403, 'المساعد مقفول.');
231:         $disabled = $this->settings->get('ai_disabled_tools', []);
232:         abort_if(is_array($disabled) && in_array($action->tool, $disabled, true), 403, 'الأداة مقفولة من الإعدادات.');
233:         abort_if($this->registry->isCustomerTool($action->tool) && ! $this->registry->customerToolsEnabled(), 403, 'أدوات العملاء مقفولة من الإعدادات.');
