330:         } catch (QueryException $e) {
331:             // M1: كتلة QueryException واحدة. قفل/deadlock → RetryableConflict
332:             // (409 قابل لإعادة المحاولة) من غير وسم failed (الـ savepoint
333:             // اتراجع ومفيش حالة اتغيرت). غير كده → failed برسالة مفهومة.
334:             if (in_array($e->errorInfo[0] ?? null, ['55P03', '40P01', '40001'], true) || $this->isRetryableLockFailure($e)) {
335:                 throw new RetryableConflict('السجل مشغول بتعديل تاني؛ مفيش حاجة اتنفذت. جرّب التأكيد تاني بعد لحظة.', $e);
336:             }
337:             report($e);
338:             $message = match ($e->errorInfo[0] ?? null) {
339:                 '23514' => 'البيانات مش مستوفية لشروط الحفظ (مثلاً بيانات قانونية ناقصة)؛ كمّلها واطلب اقتراح جديد.',
340:                 '23503' => 'سجل مرتبط بالإجراء اتغير أو اتحذف؛ اطلب اقتراح جديد.',
341:                 default => 'تعذّر التنفيذ بسبب خطأ في قاعدة البيانات؛ اطلب اقتراح جديد.',
342:             };
343:             $this->markFailed($action, $message);
344: 
345:             return ToolOutcome::result(false, $message);
346:         } catch (HttpExceptionInterface $e) {
347:             if ($e->getStatusCode() === 409) {
348:                 // H2: التعارض القابل لإعادة المحاولة لا يوسم failed — مفيش
349:                 // حالة اتغيرت، وإعادة التأكيد بعد لحظة كافية.
350:                 if (! $e instanceof RetryableConflict) {
351:                     $action->forceFill(['status' => 'failed', 'result' => ['message' => $e->getMessage() ?: 'حد عدّل السجل ده بعد الاقتراح. تحب أجهّز اقتراح جديد؟', 'conflict_409' => true]])->save();
352:                     $this->event($action, 'result', $e->getMessage() ?: 'حد عدّل السجل ده بعد الاقتراح.', [['type' => 'result', 'ok' => false, 'message' => $e->getMessage() ?: 'حد عدّل السجل ده بعد الاقتراح.']]);
353:                 }
354:             }
355:             throw $e;
356:         }
357: 
358:         return $this->finalizeAction($action, $outcome);
359:     }
