428:     private function undoLocked(User $actor, AiPendingAction $action): ToolOutcome
429:     {
430:         abort_unless($action->user_id === $actor->id, 403);
431:         $this->authorizeTool($actor, $action);
432:         abort_unless($this->registry->canUndo($action), 409);
433:         abort_unless(isset($action->result['undo_state']) && hash_equals($action->result['undo_state'], $this->registry->targetState($action)), 409, 'السجل اتعدل بعد التنفيذ؛ التراجع مش آمن.');
434:         abort_unless($action->status === 'executed' && $action->executed_at && $action->executed_at->copy()->addMinutes(15)->isFuture(), 409, 'التراجع مش متاح.');
435:         abort_unless($actor->can('ai_agent.execute'), 403);
436:         $via = ['channel' => 'ai', 'conversation_id' => $action->conversation_id, 'action_id' => $action->id];
437:         try {
438:             $outcome = $this->registry->executeUndo($actor, $action, $via);
439:         } catch (BusinessException $e) {
440:             if ($e->status === 409) {
441:                 $this->event($action, 'result', 'التراجع اترفض عشان السجل اتعدل.', [['type' => 'result', 'ok' => false, 'message' => 'التراجع اترفض: السجل اتعدل بعد التنفيذ.']]);
442:                 abort(409, $e->getMessage());
443:             }
444:             return ToolOutcome::result(false, $e->getMessage() ?: 'فشل التراجع.');
445:         } catch (HttpExceptionInterface $e) {
446:             if ($e->getStatusCode() === 409) {
447:                 $this->event($action, 'result', 'التراجع اترفض عشان السجل اتعدل.', [['type' => 'result', 'ok' => false, 'message' => 'التراجع اترفض: السجل اتعدل بعد التنفيذ.']]);
448:                 throw $e;
449:             } throw $e;
450:         }
451:         if ($outcome->type === 'result') {
452:             $action->forceFill(['status' => 'undone'])->save();
453:             $this->event($action, 'result', 'تم التراجع.', [['type' => 'result', 'ok' => true, 'message' => 'تم التراجع.']]);
454:         }
455: 
456:         return $outcome;
457:     }
