 985:     private function customerSearchQuery(array $args)
 986:     {
 987:         $query = (string) ($args['query'] ?? '');
 988:         $q = Customer::query()->with('customerGroup')
 989:             ->when($args['business_only'] ?? false, fn ($x) => $x->whereIn('type', ['wholesale', 'distributor']))
 990:             ->when(isset($args['type']), fn ($x) => $x->where('type', $args['type']))
 991:             ->when(isset($args['status']), fn ($x) => $x->where('status', $args['status']))
 992:             ->when(isset($args['customer_group_id']), fn ($x) => $x->where('customer_group_id', $args['customer_group_id']))
 993:             ->when(isset($args['pending_older_than_hours']), fn ($x) => $x->where('status', 'pending')->where('created_at', '<', now()->subHours((int) $args['pending_older_than_hours'])));
 994:         if (trim($query) !== '') {
 995:             if (preg_match('/^[0-9٠-٩۰-۹\s().+-]+$/u', trim($query))) {
 996:                 // L5: LIKE مش ILIKE عشان يستخدم index الـ text_pattern_ops.
 997:                 $q->whereLike('phone', SearchTerm::prefix(Customer::normalizePhone($query)), caseSensitive: true);
 998:             } else {
 999:                 $q->whereLike('search_text', SearchTerm::pattern($query), caseSensitive: false);
1000:             }
1001:         }
1002: 
1003:         return $q;
1004:     }
1005: 
1006:     private function listCustomers(array $args): ToolOutcome
1007:     {
1008:         $limit = min(20, max(1, (int) ($args['limit'] ?? 20)));
1009:         $rows = $this->customerSearchQuery($args)->orderBy('id')->limit($limit)->get();
1010:         $data = $rows->map(fn (Customer $c) => [
1011:             'id' => $c->id,
1012:             'name' => $this->untrusted($c->name),
1013:             'company_name' => $this->untrusted($c->company_name),
1014:             'phone_masked' => EntityResolver::maskPhone($c->phone),
1015:             'type' => $c->type->value,
1016:             'status' => $c->status->value,
1017:             'group' => $c->customerGroup?->name,
1018:             'age_hours' => $c->created_at->diffInHours(now()),
1019:         ])->all();
1020: 
1021:         return ToolOutcome::data(['customers' => $data], ['type' => 'table', 'columns' => ['الاسم', 'الشركة', 'الحالة', 'النوع', 'المجموعة', 'عمر الطلب (ساعة)'], 'rows' => $rows->map(fn (Customer $c) => [$c->name, $c->company_name ?? '—', EntityResolver::statusLabel($c->status->value), EntityResolver::typeLabel($c->type->value), $c->customerGroup?->name ?? '—', $c->created_at->diffInHours(now())])->all()]);
1022:     }
