1024:     private function getCustomerProfile(array $args): ToolOutcome
1025:     {
1026:         $customer = $this->findCustomer($args);
1027:         if (! $customer) {
1028:             return ToolOutcome::denied('العميل مش موجود.');
1029:         }
1030:         $customer->load(['customerGroup', 'documents']);
1031:         $counts = ['total' => $customer->documents->count(), 'pending' => 0, 'verified' => 0, 'rejected' => 0];
1032:         foreach ($customer->documents as $doc) {
1033:             $counts[$doc->status->value] = ($counts[$doc->status->value] ?? 0) + 1;
1034:         }
1035:         $used = app(WholesalePaymentNoticeService::class)->outstandingBalance($customer);
1036:         $data = [
1037:             'id' => $customer->id,
1038:             'name' => $this->untrusted($customer->name),
1039:             'company_name' => $this->untrusted($customer->company_name),
1040:             'email' => $this->untrusted($customer->email),
1041:             'phone_masked' => EntityResolver::maskPhone($customer->phone),
1042:             'tax_number_masked' => EntityResolver::maskLegal($customer->tax_number),
1043:             'commercial_register_masked' => EntityResolver::maskLegal($customer->commercial_register),
1044:             'type' => $customer->type->value,
1045:             'status' => $customer->status->value,
1046:             'group' => $customer->customerGroup ? ['id' => $customer->customerGroup->id, 'name' => $customer->customerGroup->name, 'discount_percentage' => $customer->customerGroup->discount_percentage] : null,
1047:             'credit_limit' => (float) $customer->credit_limit,
1048:             'used_credit' => $used,
1049:             'documents_counts' => $counts,
1050:             'pending_age_hours' => $customer->status === CustomerStatus::Pending ? $customer->created_at->diffInHours(now()) : null,
1051:             'created_at' => $customer->created_at,
1052:         ];
1053: 
1054:         // M6: الـ block بيتخزن في ai_messages.ui_blocks — قيم مقنّعة بس؛ الكامل في ملف التاجر.
1055:         return ToolOutcome::data(['customer' => $data], ['type' => 'customer_card', 'deep_link' => '/dealers?customer='.$customer->id, 'id' => $customer->id, 'name' => $customer->name, 'company_name' => $customer->company_name, 'email' => $customer->email ? $this->resolver->maskEmail($customer->email) : null, 'phone' => EntityResolver::maskPhone($customer->phone), 'tax_number' => EntityResolver::maskLegal($customer->tax_number), 'commercial_register' => EntityResolver::maskLegal($customer->commercial_register), 'customer_type' => $customer->type->value, 'status' => $customer->status->value, 'group' => $customer->customerGroup?->name, 'credit_limit' => (float) $customer->credit_limit, 'used_credit' => $used, 'documents_counts' => $counts]);
