1628:     private function prepSetCustomerGroup(User $actor, AiConversation $conv, array $args): ToolOutcome
1629:     {
1630:         $customer = $this->findCustomer($args);
1631:         if (! $customer) {
1632:             return ToolOutcome::denied('العميل مش موجود.');
1633:         }
1634:         $group = CustomerGroup::find((int) $args['customer_group_id']);
1635:         if (! $group) {
1636:             return ToolOutcome::denied('المجموعة مش موجودة.');
1637:         }
1638:         $warnings = ! $group->is_active ? ['المجموعة مش مفعلة.'] : [];
1639: 
1640:         return $this->makeProposal($actor, $conv, 'set_customer_group', ['customer_id' => $customer->id, 'customer_group_id' => $group->id], ['customer:'.$customer->id => $this->customerVersion($customer)], ['title' => 'تعيين مجموعة '.$customer->name, 'before' => ['customer_group' => $customer->customerGroup?->name], 'after' => ['customer_group' => $group->name], 'warnings' => $warnings], ['customer_group_id' => $customer->customer_group_id], 'medium');
1641:     }
