1795:     private function prepCreateCustomerGroup(User $actor, AiConversation $conv, array $args): ToolOutcome
1796:     {
1797:         try {
1798:             $this->branches->assertCentralAccess($actor);
1799:         } catch (\Throwable) {
1800:             return ToolOutcome::denied('إدارة مجموعات العملاء محتاجة وصول مركزي.');
1801:         }
1802:         $data = ['name' => (string) $args['name'], 'code' => (string) $args['code']];
1803:         foreach (['description', 'discount_percentage', 'is_active'] as $field) {
1804:             if (array_key_exists($field, $args)) {
1805:                 $data[$field] = $args[$field];
1806:             }
1807:         }
1808: 
1809:         return $this->makeProposal($actor, $conv, 'create_customer_group', $data, [], ['title' => 'إنشاء مجموعة '.$data['name'], 'after' => $data, 'warnings' => []], null, 'low');
