1998:     /**
1999:      * 0.6: بصمة نسخة للعميل — حقول مستقرة فقط. wallet_balance وupdated_at
2000:      * متعمد غيابهما: بيتغيروا مع كل طلب/حركة محفظة، ولو دخلوا في البصمة
2001:      * كل كارت تأكيد كان هيتلغي بـ 409 من غير سبب حقيقي.
2002:      * 2.3: name دخلت مع أدوات الكتابة — update_customer_profile بيكتبها،
2003:      * وتعديلها من REST بين الاقتراح والتأكيد لازم يرفض بـ 409.
2004:      */
2005:     private const CUSTOMER_VERSION_FIELDS = [
2006:         'name', 'status', 'type', 'customer_group_id', 'credit_limit', 'company_name',
2007:         'tax_number', 'commercial_register', 'email', 'phone', 'deleted_at',
2008:         'rejection_reason', 'suspension_reason',
2009:     ];
