2748:     private function execApproveDealerApplication(User $actor, array $args, array $via, AiPendingAction $action): ToolOutcome
2749:     {
2750:         $service = app(CustomerManagementService::class);
2751:         $customer = Customer::findOrFail($args['customer_id']);
2752:         foreach ($args['verify_document_ids'] ?? [] as $docId) {
2753:             $doc = $customer->documents()->whereKey($docId)->firstOrFail();
2754:             $service->reviewDocument($customer, $doc, CustomerDocumentStatus::Verified->value, $actor->id, null, $via);
2755:         }
2756:         $data = [];
2757:         foreach (['customer_group_id', 'credit_limit', 'type'] as $field) {
2758:             if (array_key_exists($field, $args)) {
2759:                 $data[$field] = $args[$field];
2760:             }
2761:         }
2762:         $service->approve($customer, $data, $actor->id, $via);
2763: 
2764:         return ToolOutcome::result(true, 'تم اعتماد التاجر.', ['customer_id' => $customer->id], ['type' => 'result', 'ok' => true, 'message' => 'تم اعتماد التاجر.', 'deep_link' => '/dealers?customer='.$customer->id]);
