2767:     private function execRejectDealerApplication(User $actor, array $args, array $via, AiPendingAction $action): ToolOutcome
2768:     {
2769:         $service = app(CustomerManagementService::class);
2770:         $customer = Customer::findOrFail($args['customer_id']);
2771:         $notes = $args['document_notes'] ?? [];
2772:         foreach ($args['reject_document_ids'] ?? [] as $docId) {
2773:             $doc = $customer->documents()->whereKey($docId)->firstOrFail();
2774:             $note = $notes[$docId] ?? $notes[(string) $docId] ?? null;
2775:             $service->reviewDocument($customer, $doc, CustomerDocumentStatus::Rejected->value, $actor->id, $note, $via);
2776:         }
2777:         $service->reject($customer, $args['reason'], $actor->id, $via);
2778: 
2779:         return ToolOutcome::result(true, 'تم رفض الطلب.', ['customer_id' => $customer->id], ['type' => 'result', 'ok' => true, 'message' => 'تم رفض الطلب.', 'deep_link' => '/dealers?customer='.$customer->id]);
2780:     }
