2782:     private function execSuspendCustomer(User $actor, array $args, array $via, AiPendingAction $action): ToolOutcome
2783:     {
2784:         $customer = Customer::findOrFail($args['customer_id']);
2785:         app(CustomerManagementService::class)->suspend($customer, $args['reason'], $actor->id, $via);
