140:     /**
141:      * Return all settings grouped by their group name, with values cast to their declared types.
142:      * Numbering counters are read fresh because they change for every generated document number.
143:      *
144:      * @return array<string, array<string, mixed>>
145:      */
146:     public function getAllGrouped(): array
147:     {
148:         $grouped = $this->staticSettings();
149: 
150:         $counters = Setting::query()
151:             ->whereIn('key', self::NUMBERING_COUNTER_KEYS)
152:             ->orderBy('key')
153:             ->get()
154:             ->mapWithKeys(fn (Setting $setting): array => [
155:                 $setting->key => $this->castValue($setting->value, $setting->type),
156:             ])
157:             ->all();
158: 
159:         if (isset($counters['movement_next_number'])) {
160:             $counters['movement_next_number'] = $this->nextMovementNumber();
161:         }
162:         foreach (self::SEQUENCE_TYPES as $type => $key) {
163:             if (isset($counters[$key])) {
164:                 $counters[$key] = $this->nextDocumentNumber($type);
165:             }
166:         }
167: 
168:         if ($counters !== []) {
169:             $grouped['numbering'] = array_merge($grouped['numbering'] ?? [], $counters);
170:             ksort($grouped['numbering']);
171:         }
172: 
173:         return $grouped;
174:     }
