227:     public function get(string $key, mixed $default = null): mixed
228:     {
229:         if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
230:             if ($key === 'movement_next_number') {
231:                 return $this->nextMovementNumber();
232:             }
233:             $type = array_search($key, self::SEQUENCE_TYPES, true);
234:             if (is_string($type)) {
235:                 return $this->nextDocumentNumber($type);
236:             }
237:             $setting = Setting::query()->where('key', $key)->first();
238: 
239:             return $setting ? $this->castValue($setting->value, $setting->type) : $default;
240:         }
241:         foreach ($this->staticSettings() as $settings) {
242:             if (array_key_exists($key, $settings)) {
243:                 return $settings[$key];
244:             }
245:         }
246: 
247:         if ($default === null && array_key_exists($key, self::DEFAULTS)) {
248:             return self::DEFAULTS[$key];
249:         }
250: 
251:         return $default;
252:     }
