 25: /**
 26:  * Inter-branch inventory transfer service managing draft, approval, dispatch, and receiving stages.
 27:  *
 28:  * All inventory ledger side effects are coordinated exclusively via InventoryService:
 29:  * - draft: No inventory side effects.
 30:  * - approve: Reserves approved quantities at source branch to prevent concurrent overselling.
 31:  * - ship: Releases source reserve, issues TransferOut from on_hand, and records TransferInTransit at destination.
 32:  * - receive: Clears TransferTransitRelease from in_transit, adds TransferIn to on_hand, and writes off shortages.
 33:  */
 34: class TransferService
 35: {
 36:     use HandlesIdempotentCreation;
 37: 
 38:     public function __construct(
 39:         private readonly InventoryService $inventory,
 40:         private readonly SettingService $settings,
 41:     ) {}
 42: 
 43:     /**
 44:      * Paginates inter-branch transfers filtered by branch and status.
 45:      *
 46:      * @param  array<string, mixed>  $filters
 47:      */
 48:     public function paginate(array $filters): LengthAwarePaginator
 49:     {
 50:         return StockTransfer::query()
 51:             ->when($filters['staff_branch_id'] ?? null, fn ($q, $branch) => $q->where(fn ($scope) => $scope->where('from_branch_id', $branch)->orWhere('to_branch_id', $branch)))
 52:             ->with(['fromBranch', 'toBranch', 'creator'])
 53:             ->when($filters['from_branch_id'] ?? null, fn ($q, $v) => $q->where('from_branch_id', $v))
 54:             ->when($filters['to_branch_id'] ?? null, fn ($q, $v) => $q->where('to_branch_id', $v))
 55:             ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
 56:             ->orderByDesc('id')
 57:             ->paginate($filters['per_page'] ?? 15);
 58:     }
