 60:     /**
 61:      * Retrieves a single stock transfer with items, branches, and audit relations.
 62:      */
 63:     public function find(int $id): StockTransfer
 64:     {
 65:         return StockTransfer::query()
 66:             ->with(['items.variant', 'items.fromLocation', 'items.toLocation', 'fromBranch', 'toBranch', 'creator', 'approver'])
 67:             ->findOrFail($id);
