 70:     /**
 71:      * Creates a new stock transfer draft with optional idempotency protection.
 72:      *
 73:      * @param  array<string, mixed>  $data
 74:      */
 75:     public function create(array $data, int $userId, ?string $idempotencyKey = null): StockTransfer
 76:     {
 77:         // Transfers may be initiated from source (warehouse dispatch) or destination branch (POS replenishment request).
 78:         $this->assertCreateAccess($userId, (int) $data['from_branch_id'], (int) $data['to_branch_id']);
 79: 
 80:         /** @var StockTransfer */
 81:         return $this->createIdempotently(
 82:             'transfer_store',
 83:             $data,
 84:             $userId,
 85:             $idempotencyKey,
 86:             StockTransfer::class,
 87:             ['items.variant', 'fromBranch', 'toBranch', 'creator'],
 88:             fn (): StockTransfer => $this->doCreate($data, $userId),
 89:         );
 90:     }
