 99:     public function run(): void
100:     {
101:         $now = now();
102:         $rows = array_map(
103:             static fn (array $setting): array => [
104:                 ...$setting,
105:                 'created_at' => $now,
106:                 'updated_at' => $now,
107:             ],
108:             self::SETTINGS,
109:         );
110: 
111:         Setting::query()->insertOrIgnore($rows);
112:         DB::afterCommit(fn () => app(SettingService::class)->clearCache());
113:     }
