  45: 
  46: function CategoryTreeView({ nodes, movedId }: { nodes: CategoryTreeNode[]; movedId?: number }) {
  47:   const [collapsedIds, setCollapsedIds] = useState<Record<number, boolean>>({});
  48:   const renderNode = (node: CategoryTreeNode, depth = 0) => {
  49:     const label = node.name ?? node.name_ar ?? `#${node.id}`;
  50:     const active = node.active ?? node.is_active ?? true;
  51:     const children = node.children ?? [];
  52:     const hasChildren = children.length > 0;
  53:     const isCollapsed = !!collapsedIds[node.id];
  54:     const isMoved = movedId != null && Number(node.id) === Number(movedId);
  55:     return (
  56:       <li key={node.id} style={{ listStyle: 'none', marginTop: '.25rem' }}>
  57:         <div
  58:           style={{
  59:             display: 'flex',
  60:             alignItems: 'center',
  61:             gap: '.45rem',
  62:             padding: '.3rem .5rem',
  63:             paddingInlineStart: `${depth * 1.1 + 0.5}rem`,
  64:             borderRadius: 6,
  65:             opacity: active ? 1 : 0.55,
  66:             background: isMoved ? 'var(--as-accent-soft, rgba(59,130,246,.12))' : undefined,
  67:             border: isMoved ? '1px solid var(--as-accent, #3b82f6)' : '1px solid transparent',
  68:           }}
  69:         >
  70:           {hasChildren ? (
  71:             <button
  72:               type="button"
  73:               className="as-iconbtn as-iconbtn--sm"
  74:               aria-expanded={!isCollapsed}
  75:               onClick={() => setCollapsedIds(prev => ({ ...prev, [node.id]: !prev[node.id] }))}
  76:             >
  77:               <Icon name={isCollapsed ? 'chevronStart' : 'chevron'} size={14} />
  78:             </button>
  79:           ) : (
  80:             <span style={{ width: 22, display: 'inline-flex', justifyContent: 'center' }}><Icon name="folder" size={14} /></span>
  81:           )}
  82:           <span style={{ fontWeight: isMoved ? 600 : 500 }}>{label}</span>
  83:           {!active && <span className="as-badge">متوقف</span>}
  84:           {isMoved && <span className="as-badge as-badge--info">منقول</span>}
  85:           {node.products_count != null && (
  86:             <span className="as-num" style={{ marginInlineStart: 'auto', fontSize: '.78rem', color: 'var(--as-muted)' }}>
  87:               {node.products_count} منتج
  88:             </span>
  89:           )}
  90:         </div>
  91:         {hasChildren && !isCollapsed && (
  92:           <ul style={{ margin: 0, padding: 0 }}>
  93:             {children.map(child => renderNode(child, depth + 1))}
  94:           </ul>
  95:         )}
  96:       </li>
  97:     );
  98:   };
  99:   return (
 100:     <ul style={{ margin: 0, padding: 0 }}>
 101:       {nodes.map(n => renderNode(n, 0))}
 102:     </ul>
 103:   );
 104: }
