 106: function formatValue(key: string, item: unknown): string {
 107:   if (key === 'is_active' || key === 'is_featured') return item ? 'نعم / نشط' : 'لا / متوقف';
 108:   if (key === 'status' || key === 'previous_status') return customerStatusLabels[String(item)] ?? String(item ?? 'بدون');
 109:   if (key === 'sales_channel') return customerTypeLabels[String(item)] ?? String(item ?? 'بدون');
 110:   if (key === 'credit_limit' || key === 'used_credit' || key === 'retail_price' || key === 'wholesale_price' || key === 'compare_at_price' || key === 'cost_price') return item != null && item !== '' ? money(item) : 'بدون';
 111:   if (item && typeof item === 'object' && !Array.isArray(item)) {
 112:     const rec = item as Record<string, unknown>;
 113:     if ('untrusted_text' in rec) return String(rec.untrusted_text ?? 'بدون');
 114:     const parts = Object.entries(rec).filter(([, v]) => v != null && v !== '').map(([k, v]) => `${fieldLabels[k] ?? k}: ${typeof v === 'object' ? JSON.stringify(v) : String(v)}`);
 115:     return parts.join(' · ') || 'بدون';
 116:   }
 117:   if (Array.isArray(item)) return item.map(String).map(v => (key === 'permissions' ? permLabel(v) : v)).join('، ') || 'بدون';
 118:   if (item == null || item === '') return 'بدون';
 119:   return String(item);
 120: }
 121: const asRecord = (v: unknown): Record<string, unknown> | null => (v && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : null);
 122: 
 123: // جدول مقارنة قبل/بعد — بيعلّم الحقول اللي اتغيرت فعلاً.
 124: function DiffTable({ before, after }: { before: unknown; after: unknown }) {
 125:   const b = asRecord(before); const a = asRecord(after);
 126:   if (!b && !a) return null;
 127:   const keys = Array.from(new Set([...Object.keys(b ?? {}), ...Object.keys(a ?? {})]));
 128:   // عنصر جديد (مفيش «قبل») — نعرض القيم بس بدل عمود فاضي.
 129:   if (!b && a) {
 130:     return (
 131:       <div className="as-diff as-diff--new" aria-label="بيانات العنصر الجديد">
 132:         <div className="as-diff-head"><span>الحقل</span><span>القيمة الجديدة</span></div>
 133:         <dl>
 134:           {keys.map(key => (
 135:             <div className="as-diff-row" key={key}>
 136:               <dt>{fieldLabels[key] ?? key}</dt>
 137:               <dd className="as-after">{formatValue(key, a[key])}</dd>
 138:             </div>
 139:           ))}
 140:         </dl>
 141:       </div>
 142:     );
 143:   }
 144:   return (
 145:     <div className="as-diff" role="table" aria-label="مقارنة قبل وبعد التعديل">
 146:       <div className="as-diff-head" role="row"><span role="columnheader">الحقل</span><span role="columnheader">قبل التعديل</span><span role="columnheader">بعد التعديل</span></div>
 147:       <dl>
 148:         {keys.map(key => {
 149:           const bv = b ? formatValue(key, b[key]) : '—';
 150:           const av = a && key in a ? formatValue(key, a[key]) : bv;
 151:           const changed = !!a && key in a && (!b || bv !== av);
 152:           return (
 153:             <div className="as-diff-row" role="row" key={key} data-changed={changed}>
 154:               <dt role="cell">{fieldLabels[key] ?? key}</dt>
 155:               <dd role="cell" className="as-before">{b ? <span className={bv === 'بدون' ? 'as-empty-val' : ''}>{bv}</span> : <span className="as-empty-val">جديد</span>}</dd>
 156:               <dd role="cell" className="as-after"><span className={av === 'بدون' ? 'as-empty-val' : ''}>{av}</span></dd>
 157:             </div>
 158:           );
 159:         })}
 160:       </dl>
 161:     </div>
 162:   );
 163: }
