 60: const CUSTOMER_COMMANDS = ['/تجار-معلقين', '/راجع-تاجر', '/مجموعات-العملاء'];
 61: const CATALOG_COMMANDS = ['/منتج-جديد', '/جاهزية P00042', '/صحة-الكتالوج', '/أسعار', '/قسم-جديد'];
 62: const QUICK_COMMANDS = ['/ملخص الفروع', '/موظفين بدون دور', '/صلاحيات حساسة', '/آخر التعديلات'];
 63: const INVENTORY_COMMANDS = ['/رصيد', '/تحويل', '/جرد', '/استلام'];
 64: 
 65: const dayKey = (iso: string | null) => {
 66:   if (!iso) return 'older';
 67:   const d = new Date(iso); const t = new Date();
 68:   const start = (x: Date) => new Date(x.getFullYear(), x.getMonth(), x.getDate()).getTime();
 69:   const diff = Math.round((start(t) - start(d)) / 86400000);
 70:   return diff <= 0 ? 'today' : diff === 1 ? 'yesterday' : diff < 7 ? 'week' : 'older';
 71: };
 72: const groupTitles: Record<string, string> = { pinned: 'المثبّتة', today: 'النهارده', yesterday: 'امبارح', week: 'آخر ٧ أيام', older: 'أقدم' };
 73: const relTime = (iso: string | null) => {
 74:   if (!iso) return '';
 75:   const d = new Date(iso);
 76:   return dayKey(iso) === 'today' ? d.toLocaleTimeString('ar-EG', { hour: 'numeric', minute: '2-digit' }) : d.toLocaleDateString('ar-EG', { day: 'numeric', month: 'short' });
 77: };
