 79: export default function AssistantPage({ can, theme, initialConversationId, initialPrompt }: { can: (permission: string) => boolean; theme?: 'light' | 'dark'; initialConversationId?: number; initialPrompt?: { text: string; mentions?: Mention[] } }) {
 80:   const [resolvedTheme, setResolvedTheme] = useState<'light' | 'dark'>(() => {
 81:     if (theme) return theme;
 82:     if (typeof document !== 'undefined') {
 83:       const doc = document.documentElement.getAttribute('data-theme');
 84:       if (doc === 'dark' || doc === 'light') return doc;
 85:     }
 86:     return 'light';
 87:   });
 88: 
 89:   useEffect(() => {
 90:     if (theme) {
 91:       setResolvedTheme(theme);
 92:       return;
 93:     }
 94:     const update = () => {
 95:       const doc = document.documentElement.getAttribute('data-theme');
 96:       if (doc === 'dark' || doc === 'light') setResolvedTheme(doc);
 97:     };
 98:     const observer = new MutationObserver(update);
 99:     observer.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });
100:     return () => observer.disconnect();
101:   }, [theme]);
102: 
103:   const [conversations, setConversations] = useState<Conv[]>([]);
104:   const [listLoading, setListLoading] = useState(true);
105:   const [currentId, setCurrentId] = useState<number | null>(null);
106:   const [messages, setMessages] = useState<ConvMsg[]>([]);
107:   const [actionStatus, setActionStatus] = useState<Record<string, string>>({});
108:   const [busy, setBusy] = useState(false);
109:   const [streaming, setStreaming] = useState(false);
110:   const [status, setStatus] = useState('جاهز');
111:   const [steps, setSteps] = useState<string[]>([]);
112:   const [startedAt, setStartedAt] = useState(0);
113:   const [pendingText, setPendingText] = useState<{ text: string; mentions: Mention[] } | null>(null);
114:   const [error, setError] = useState<{ message: string; kind: ReturnType<typeof apiErrorKind>; retry?: () => void } | null>(null);
115:   const [searchQuery, setSearchQuery] = useState('');
116:   const [debouncedQuery, setDebouncedQuery] = useState('');
117:   const [oncePassword, setOncePassword] = useState('');
118:   const [copied, setCopied] = useState(false);
119:   const [revealed, setRevealed] = useState(false);
120:   const [tab, setTab] = useState<'chat' | 'admin'>('chat');
121:   const [drawer, setDrawer] = useState(false);
122:   const [collapsed, setCollapsed] = useState(false);
123:   const [confirmDelete, setConfirmDelete] = useState<number | null>(null);
124:   const [seed, setSeed] = useState<{ text: string; n: number; mentions?: Mention[] }>();
125:   const [welcomeBlock, setWelcomeBlock] = useState<UiBlock | null>(null);
126:   const canCustomers = can('customers.view');
127:   const canCatalog = can('products.view') || can('categories.view');
128:   const canInventory = can('inventory.view');
129:   const starters = [
130:     ...STARTERS,
131:     ...(canCustomers ? CUSTOMER_STARTERS : []),
132:     ...(canCatalog ? CATALOG_STARTERS : []),
133:   ];
134:   const quickCommands = [
135:     ...QUICK_COMMANDS,
136:     ...(canCustomers ? CUSTOMER_COMMANDS : []),
137:     ...(canCatalog ? CATALOG_COMMANDS : []),
138:     ...(canInventory ? INVENTORY_COMMANDS : []),
139:   ];
140: 
141:   const consumedPrompt = useRef(false);
142:   useEffect(() => {
143:     if (!initialPrompt || consumedPrompt.current) return;
144:     consumedPrompt.current = true;
145:     setSeed({ text: initialPrompt.text, mentions: initialPrompt.mentions, n: Date.now() });
146:     history.replaceState(null, '', '#/assistant');
147:   }, [initialPrompt]);
148:   const [atBottom, setAtBottom] = useState(true);
149:   const [, tick] = useState(0);
150:   const feedRef = useRef<HTMLDivElement>(null);
151:   const searchRef = useRef<HTMLInputElement>(null);
152:   const execute = can('ai_agent.execute');
153:   const current = conversations.find(c => c.id === currentId);
154: 
155:   useEffect(() => { const t = setTimeout(() => setDebouncedQuery(searchQuery), 250); return () => clearTimeout(t); }, [searchQuery]);
156: 
157:   const refreshList = useCallback(async () => {
158:     setListLoading(true);
159:     try {
160:       const page = await assistantApi.listPaginated(1, debouncedQuery);
161:       setConversations(page.data);
162:     } catch {
163:       setError({ message: 'تعذر تحميل المحادثات.', kind: 'transient', retry: () => void refreshList() });
164:     } finally {
165:       setListLoading(false);
166:     }
167:   }, [debouncedQuery]);
168: 
169:   useEffect(() => { void refreshList(); }, [refreshList]);
170: 
171:   // 5.2 / 5.4: كارت الترحيب — بيتبني في السيرفر بدون Gemini، وبيظهر في المحادثة الجديدة لمن عنده customers.approve أو products.view.
172:   const canWelcome = (can('customers.approve') && can('customers.view')) || can('products.view');
173:   useEffect(() => {
174:     if (!canWelcome || messages.length > 0) return;
175:     let live = true;
176:     assistantApi.welcome().then(block => { if (live) setWelcomeBlock(block); }).catch(() => { if (live) setWelcomeBlock(null); });
177:     return () => { live = false; };
178:   }, [canWelcome, currentId, messages.length]);
179: 
180:   useEffect(() => {
181:     if (!streaming) return;
182:     const t = setInterval(() => tick(n => n + 1), 1000);
183:     return () => clearInterval(t);
184:   }, [streaming]);
185: 
186:   const scrollToBottom = useCallback(() => {
187:     const el = feedRef.current; if (!el) return;
188:     requestAnimationFrame(() => { el.scrollTop = el.scrollHeight; });
189:   }, []);
190:   useEffect(() => { if (atBottom) scrollToBottom(); }, [messages, steps, pendingText, streaming, atBottom, scrollToBottom]);
191: 
192:   useEffect(() => {
193:     const onKey = (e: KeyboardEvent) => {
194:       const mod = e.ctrlKey || e.metaKey;
195:       if (mod && e.key.toLowerCase() === 'k') { e.preventDefault(); setTab('chat'); setCollapsed(false); setDrawer(true); setTimeout(() => searchRef.current?.focus(), 50); }
196:       if (mod && e.shiftKey && e.key.toLowerCase() === 'o') { e.preventDefault(); void createConversation(); }
197:       if (e.key === 'Escape') setDrawer(false);
198:     };
199:     window.addEventListener('keydown', onKey);
200:     return () => window.removeEventListener('keydown', onKey);
201:   });
202: 
203:   const openConversation = useCallback(async (id: number) => {
204:     setBusy(true);
205:     setError(null);
206:     setDrawer(false);
207:     setTab('chat');
208:     try {
209:       const conv = await assistantApi.show(id);
210:       setCurrentId(conv.id);
211:       setMessages(conv.messages ?? []);
212:       const pending: Record<string, string> = {};
213:       for (const action of conv.pending_actions ?? []) pending[String(action.id)] = action.status;
214:       setActionStatus(pending);
215:       setConversations(prev => prev.map(c => (c.id === conv.id ? { ...c, ...conv, messages: undefined } : c)));
216:       setAtBottom(true);
217:     } catch {
218:       setError({ message: 'تعذر فتح المحادثة.', kind: 'transient', retry: () => void openConversation(id) });
219:     } finally {
220:       setBusy(false);
221:     }
222:   }, []);
223: 
224:   useEffect(() => { if (initialConversationId) void openConversation(initialConversationId); }, [initialConversationId, openConversation]);
225: 
226:   const createConversation = useCallback(async () => {
227:     if (currentId && messages.length === 0) { setDrawer(false); setTab('chat'); return; }
228:     setBusy(true);
229:     setError(null);
230:     try {
231:       const conv = await assistantApi.create();
232:       setConversations(prev => [conv, ...prev]);
233:       setCurrentId(conv.id);
234:       setMessages([]);
235:       setActionStatus({});
236:       setDrawer(false);
237:       setTab('chat');
238:     } catch {
239:       setError({ message: 'تعذر إنشاء محادثة.', kind: 'transient', retry: () => void createConversation() });
240:     } finally {
241:       setBusy(false);
242:     }
243:   }, [currentId, messages.length]);
244: 
245:   const deleteConversation = useCallback(async (id: number) => {
246:     setConfirmDelete(null);
247:     try {
248:       await assistantApi.remove(id);
249:       setConversations(prev => prev.filter(c => c.id !== id));
250:       if (currentId === id) { setCurrentId(null); setMessages([]); }
251:     } catch {
252:       setError({ message: 'تعذر حذف المحادثة.', kind: 'transient' });
253:     }
254:   }, [currentId]);
