256:   const togglePin = useCallback(async (c: Conv) => {
257:     setConversations(prev => prev.map(x => (x.id === c.id ? { ...x, is_pinned: !c.is_pinned } : x)));
258:     try { await assistantApi.pin(c.id, !c.is_pinned); }
259:     catch {
260:       setConversations(prev => prev.map(x => (x.id === c.id ? { ...x, is_pinned: c.is_pinned } : x)));
261:       setError({ message: 'تعذر تثبيت المحادثة.', kind: 'transient' });
262:     }
263:   }, []);
