265:   const send = useCallback(
266:     async (text: string, _selection?: undefined, mentions?: Mention[], files?: File[]): Promise<boolean> => {
267:       let id = currentId;
268:       if (!id) {
269:         try {
270:           const conv = await assistantApi.create();
271:           id = conv.id;
272:           setConversations(prev => [conv, ...prev]);
273:           setCurrentId(id);
274:         } catch {
275:           setError({ message: 'تعذر إنشاء محادثة.', kind: 'transient' });
276:           return false;
277:         }
278:       }
279:       setBusy(true);
280:       setStreaming(true);
281:       setStatus(files?.length ? 'برفع الصور…' : 'ببعت الطلب…');
282:       setSteps([]);
283:       setStartedAt(Date.now());
284:       setPendingText({ text, mentions: mentions ?? [] });
285:       setError(null);
286:       setAtBottom(true);
287:       try {
288:         let attachmentIds: string[] | undefined;
289:         if (files && files.length > 0) {
290:           const uploaded = await assistantApi.uploadAttachments(id, files);
291:           attachmentIds = uploaded.map(u => u.id);
292:           setStatus('ببعت الطلب…');
293:         }
294:         await assistantApi.stream(
295:           id,
296:           { text, mentions: mentions?.map(m => ({ entity: m.entity, id: m.id })), attachments: attachmentIds },
297:           message => {
298:             setStatus(prev => {
299:               if (prev !== message && prev !== 'جاهز') setSteps(s => (s.at(-1) === prev ? s : [...s, prev].slice(-4)));
300:               return message;
301:             });
302:           },
303:         );
304:         setStreaming(false);
305:         setPendingText(null);
306:         await openConversation(id);
307:         return true;
308:       } catch (e) {
309:         const convId = id;
310:         setError({
311:           message: apiErrorMessage(e, 'تعذر إتمام طلب المساعد. حاول مرة تانية.'),
312:           kind: apiErrorKind(e),
313:           retry: apiErrorKind(e) === 'budget' ? undefined : () => { setCurrentId(convId); void send(text, undefined, mentions, files); },
314:         });
315:         return false;
316:       } finally {
317:         setBusy(false);
318:         setStreaming(false);
319:         setPendingText(null);
320:         setStatus('جاهز');
321:       }
322:     },
323:     [currentId, openConversation],
324:   );
325: 
326:   const pick = useCallback(
327:     async (entity: string, id: string | number, label: string) => {
328:       if (!currentId) return;
329:       if (entity === 'reason') {
330:         await send(`السبب: ${label}`);
331:         return;
332:       }
333:       await send(`اخترت: ${label}`, undefined, [{ entity, id, label }]);
334:     },
335:     [currentId, send],
336:   );
