338:   const act = useCallback(
339:     async (kind: 'confirm' | 'cancel' | 'undo', id: string, typed?: string, selected?: string[]) => {
340:       setBusy(true);
341:       setError(null);
342:       try {
343:         if (kind === 'confirm') {
344:           const res = await assistantApi.confirm(id, typed, selected);
345:           const pw = (res.result as { generated_password?: unknown } | undefined)?.generated_password;
346:           if (typeof pw === 'string' && pw !== '') { setOncePassword(pw); setCopied(false); setRevealed(false); }
347:         } else if (kind === 'cancel') await assistantApi.cancel(id);
348:         else await assistantApi.undo(id);
349:         if (currentId) await openConversation(currentId);
350:       } catch (e) {
351:         setError({ message: apiErrorMessage(e, 'تعذر تنفيذ الإجراء.'), kind: apiErrorKind(e) });
352:       } finally {
353:         setBusy(false);
354:       }
355:     },
356:     [currentId, openConversation],
357:   );
