  31:   const [f, setF] = useState(blank);
  32:   const [err, setErr] = useState({});
  33:   const [busy, setBusy] = useState(false);
  34:   useEffect(() => { if (open) {
  35:     setF(initial ? { id: initial.id, name: initial.name || '', code: initial.code || '', type: initial.type || 'branch', phone: initial.phone || '', email: initial.email || '', address: initial.address || '', city: initial.city || '', active: initial.is_active } : blank);
  36:     setErr({}); setBusy(false);
  37:   } }, [open]);
  38:   const set = (k, v) => setF(p => ({ ...p, [k]: v }));
  39:   const submit = async () => {
  40:     const e = {};
  41:     if (!f.name.trim()) e.name = 'الاسم مطلوب';
  42:     if (!f.code.trim()) e.code = 'الكود مطلوب';
  43:     if (f.email.trim() && !/^\S+@\S+\.\S+$/.test(f.email.trim())) e.email = 'صيغة البريد غير صحيحة';
  44:     // The API leaves city optional (StoreBranchRequest: nullable) — the UI stays
  45:     // optional too on purpose instead of forcing a 422-prone required field.
  46:     setErr(e);
  47:     if (Object.keys(e).length) return;
  48:     setBusy(true);
  49:     const res = await onSave(f);
  50:     setBusy(false);
  51:     if (res && (res.fields || res.message)) setErr({ ...res.fields, ...(res.message ? { _form: res.message } : {}) });
  52:   };
  53:   return (
  54:     <Modal open={open} onClose={onClose} width="max-w-2xl"
  55:       title={initial ? 'تعديل ' + (initial.type === 'warehouse' ? 'المخزن' : 'الفرع') : 'إضافة فرع أو مخزن'}
  56:       sub="المخزن يُسجَّل كنوع من الفروع ويملك مواقع تخزين خاصة به."
  57:       footer={<>
  58:         <button className="btn btn-dark" onClick={submit} disabled={busy}>
  59:           {busy && <span className="w-3.5 h-3.5 rounded-full border-2 border-current border-t-transparent animate-spin" />}
  60:           {initial ? 'حفظ التعديلات' : 'إضافة'}
  61:         </button>
  62:         <button className="btn btn-soft" onClick={onClose}>إلغاء</button>
  63:       </>}>
  64:       <div className="space-y-4">
  65:         {err._form && <InlineAlert kind="red">{err._form}</InlineAlert>}
  66:         <div>
  67:           <span className="field-label">النوع</span>
  68:           <div className="grid grid-cols-2 gap-2.5">
  69:             {[['branch', 'فرع', 'store', 'نقطة بيع تستقبل العملاء'], ['warehouse', 'مخزن', 'warehouse', 'تخزين وتوزيع فقط']].map(([k, l, ic, d]) => (
  70:               <button key={k} type="button" onClick={() => set('type', k)}
  71:                 className={`rounded-2xl p-3.5 flex items-center gap-3 text-right transition border ${f.type === k ? 'border-[var(--accent-orange)]' : 'border-transparent'}`}
  72:                 style={{ background: f.type === k ? 'var(--accent-orange-light)' : 'var(--bg-subcard)' }}>
  73:                 <span className={`w-9 h-9 rounded-full flex items-center justify-center ${f.type === k ? 'bg-[var(--accent-orange)] text-white' : 'v-icon-well'}`}><Icon n={ic} s={16} /></span>
  74:                 <span><span className="block text-[13px] font-semibold c-primary">{l}</span><span className="block text-[11px] c-secondary">{d}</span></span>
  75:               </button>
  76:             ))}
  77:           </div>
  78:         </div>
  79:         <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
  80:           <Field label="الاسم" req error={err.name}><input className={`inp ${err.name ? 'err' : ''}`} value={f.name} onChange={e => set('name', e.target.value)} placeholder="مثال: فرع مدينة نصر" /></Field>
  81:           <Field label="الكود" req error={err.code} hint="فريد على مستوى النظام"><input dir="ltr" maxLength={50} className={`inp mono text-left ${err.code ? 'err' : ''}`} value={f.code} onChange={e => set('code', e.target.value.toUpperCase())} placeholder="BR-XXX" /></Field>
  82:           <Field label="الهاتف" error={err.phone}><input dir="ltr" className="inp num text-left" value={f.phone} onChange={e => set('phone', e.target.value)} placeholder="01xxxxxxxxx" /></Field>
  83:           <Field label="البريد الإلكتروني" error={err.email}><input dir="ltr" className={`inp mono text-left ${err.email ? 'err' : ''}`} value={f.email} onChange={e => set('email', e.target.value)} placeholder="branch@company.com" /></Field>
  84:           <Field label="المدينة" error={err.city}><input className={`inp ${err.city ? 'err' : ''}`} value={f.city} onChange={e => set('city', e.target.value)} maxLength={100} /></Field>
  85:           <Field label="العنوان" error={err.address}><input className="inp" value={f.address} onChange={e => set('address', e.target.value)} /></Field>
  86:         </div>
  87:         <div className="v-subcard p-3.5 flex items-center justify-between">
  88:           <div>
  89:             <div className="text-[13px] font-semibold c-primary">الحالة: {f.active ? 'نشط' : 'غير نشط'}</div>
