1474: function TransfersScreen({ go }) {
1475:   const { can, branchesQuery } = useInv();
1476:   const [st, setSt] = useState('all');
1477:   const [q, setQ] = useState('');
1478:   const [fromF, setFromF] = useState(null);
1479:   const [toF, setToF] = useState(null);
1480:   const allowed = canAny(can, 'transfers.view', 'transfers.manage');
1481: 
1482:   // Small cardinality like branches: fetch all pages once (per_page=100) so the
1483:   // KPIs are exact and status/branch/search filters run client-side.
1484:   const query = useApi(signal => (async () => {
1485:     const all = []; let page = 1; let last = 1;
1486:     do {
1487:       const res = await transfersApi.list({ per_page: 100, page, from_branch_id: fromF || undefined, to_branch_id: toF || undefined, status: st === 'all' ? undefined : st }, signal);
1488:       all.push(...(res.data || [])); last = res.meta?.last_page || 1; page += 1;
1489:     } while (page <= last);
1490:     return all;
1491:   })(), [fromF, toF, st]);
1492: 
1493:   if (!allowed) return <NoPerm title="التحويلات المخزنية" perm="transfers.view" go={go} />;
1494: 
1495:   const list = query.data || [];
1496:   const { phase, error } = apiPhase(query, list.length === 0);
1497:   const onRetry = () => query.reload();
1498:   const ql = q.trim().toLowerCase();
1499:   const rows = list.filter(t => (st === 'all' || t.status === st)
1500:     && (!fromF || t.from_branch?.id === fromF) && (!toF || t.to_branch?.id === toF)
1501:     && (!ql || (t.transfer_number || '').toLowerCase().includes(ql)));
1502:   const cnt = k => list.filter(t => t.status === k).length;
1503:   const active = (fromF ? 1 : 0) + (toF ? 1 : 0) + (ql ? 1 : 0) + (st !== 'all' ? 1 : 0);
1504:   const shared = branchesQuery.data || [];
1505:   const branchOptions = shared.filter(b => b.is_active).map(b => ({ value: b.id, label: `${b.name} · ${b.type === 'warehouse' ? 'مخزن' : 'فرع'}` }));
1506:   const canCreate = canAny(can, 'transfers.create', 'transfers.manage');
1507: 
1508:   return (
1509:     <section className="space-y-5">
1510:       <PageHead title="التحويلات المخزنية" sub="نقل البضاعة بين فرعين أو مخزنين عبر مراحل: مسودة ← اعتماد ← شحن ← استلام."
1511:         actions={canCreate && <button className="btn btn-dark" onClick={() => go('transfer-edit', {})}><Icon n="plus" s={14} w={2.2} /> تحويل جديد</button>} />
1512: 
1513:       <div className="grid grid-cols-2 lg:grid-cols-4 gap-3.5 stagger-item stagger-2">
1514:         <KPI label="مسودات" icon="edit" value={phase === 'ready' ? cnt('draft') : '—'} sub="بانتظار الاعتماد" />
1515:         <KPI label="معتمدة" icon="check" value={phase === 'ready' ? cnt('approved') : '—'} sub="جاهزة للشحن" />
1516:         <KPI hot label="في الطريق" icon="truck" value={phase === 'ready' ? cnt('shipped') : '—'} sub="بانتظار الاستلام" />
1517:         <KPI label="مستلمة" icon="inbox" value={phase === 'ready' ? cnt('received') : '—'} sub="تحويلات مستلمة" />
1518:       </div>
1519: 
1520:       <Card stagger={3}>
1521:         <CardHead title="القائمة" right={<>
1522:           <div className="seg">
1523:             <button className={st === 'all' ? 'on' : ''} onClick={() => setSt('all')}>الكل</button>
1524:             {Object.entries(TRANSFER_STATUS).map(([k, t]) => <button key={k} className={st === k ? 'on' : ''} onClick={() => setSt(k)}>{t}</button>)}
1525:           </div>
1526:           <SearchPill value={q} onChange={setQ} placeholder="رقم التحويل" w="w-32" />
1527:         </>} />
1528:         <FilterBar active={active} onReset={() => { setFromF(null); setToF(null); setQ(''); setSt('all'); }}>
1529:           <FItem label="من فرع"><Sel small value={fromF} onChange={v => setFromF(v || null)} placeholder="كل الفروع" options={branchOptions} className="!bg-[var(--bg-card)]" /></FItem>
1530:           <FItem label="إلى فرع"><Sel small value={toF} onChange={v => setToF(v || null)} placeholder="كل الفروع" options={branchOptions} className="!bg-[var(--bg-card)]" /></FItem>
1531:         </FilterBar>
1532:         <Phase phase={phase} cols={6} error={error} onRetry={onRetry}
1533:           empty={<EmptyState icon="swap" title="لا توجد تحويلات" sub="أنشئ أول تحويل لنقل الكميات من المخزن الرئيسي إلى الفروع."
1534:             action={canCreate && <button className="btn btn-dark btn-sm" onClick={() => go('transfer-edit', {})}><Icon n="plus" s={13} /> تحويل جديد</button>} />}>
1535:           {rows.length === 0 ? <EmptyState icon="filter" title="لا توجد تحويلات بهذه الحالة" /> : (
1536:             <table className="vt">
1537:               <thead><tr><th>رقم التحويل</th><th>المصدر ← الوجهة</th><th>التقدّم</th><th>الحالة</th><th>التاريخ</th><th></th></tr></thead>
1538:               <tbody>
1539:                 {rows.map(t => {
1540:                   const idx = TR_FLOW.indexOf(t.status);
1541:                   return (
1542:                     <tr key={t.id} className="cursor-pointer" onClick={() => go('transfer', { id: t.id })}>
1543:                       <td><span className="mono text-[12px] font-semibold c-primary" dir="ltr">{t.transfer_number}</span></td>
1544:                       <td>
1545:                         <div className="flex items-center gap-2">
1546:                           <span className="font-medium c-primary">{t.from_branch?.name || '—'}</span>
1547:                           <Icon n="arrowL" s={14} className="c-orange" />
1548:                           <span className="font-medium c-primary">{t.to_branch?.name || '—'}</span>
1549:                         </div>
1550:                       </td>
1551:                       <td>
1552:                         <div className="flex items-center gap-1 w-28">
1553:                           {TR_FLOW.slice(1).map((s, i) => <span key={s} className="h-1.5 flex-1 rounded-full" style={{ background: t.status === 'cancelled' ? 'var(--badge-red-bg)' : i < idx ? 'var(--accent-orange)' : 'var(--badge-gray-bg)' }} />)}
1554:                         </div>
1555:                       </td>
1556:                       <td><TrStatus s={t.status} /></td>
1557:                       <td className="num text-[11.5px] c-secondary">{formatDate(t.created_at)}</td>
1558:                       <td><Icon n="chevL" s={15} className="c-muted" /></td>
1559:                     </tr>
1560:                   );
1561:                 })}
1562:               </tbody>
1563:             </table>
1564:           )}
1565:         </Phase>
1566:       </Card>
1567:     </section>
1568:   );
1569: }
1570: // NOTE: the transfer list resource omits line items (TransferService::paginate
1571: // loads fromBranch/toBranch/creator only), so the old "items count" column was
1572: // dropped — the contract is the source of truth, not the mock.
1573: 
1574: function TransferEdit({ go, params }) {
1575:   const { toast, can, branchesQuery, variantCache } = useInv();
1576:   const restriction = useRestrictedBranch();
1577:   const { keyFor, reset } = useIdempotencyKey();
1578:   const editId = params.id ? Number(params.id) : null;
1579:   const [from, setFrom] = useState(restriction.locked ? restriction.branchId : null);
1580:   const [to, setTo] = useState(null);
1581:   const [note, setNote] = useState('');
1582:   const [lines, setLines] = useState(() => [newTrLine()]);
1583:   const [tried, setTried] = useState(false);
1584:   const [busy, setBusy] = useState(false);
1585:   const [srvErr, setSrvErr] = useState(null);
1586:   const [rowErrs, setRowErrs] = useState({});
1587:   const [loaded, setLoaded] = useState(!editId);
1588:   const allowed = editId ? canAny(can, 'transfers.update', 'transfers.manage') : canAny(can, 'transfers.create', 'transfers.manage');
1589: 
1590:   const showQuery = useApi(signal => (editId ? transfersApi.show(editId, signal) : Promise.resolve(null)), [editId || 0]);
1591:   useEffect(() => {
1592:     const t = showQuery.data;
1593:     if (editId && t && !loaded) {
1594:       setFrom(t.from_branch?.id ?? null); setTo(t.to_branch?.id ?? null); setNote(t.notes || '');
1595:       setLines((t.items || []).map(it => newTrLine({ variantId: it.product_variant_id, fromLoc: it.from_location?.id ?? null, toLoc: it.to_location?.id ?? null, req: it.requested_qty != null ? String(it.requested_qty) : '' })));
1596:       cacheVariantNames(variantCache, (t.items || []).map(it => ({ id: it.product_variant_id, sku: it.sku })));
1597:       setLoaded(true);
1598:     }
1599:   }, [showQuery.data]);
1600:   const fromLocsQuery = useBranchesWithLocations(from);
1601:   const toLocsQuery = useBranchesWithLocations(to);
1602: 
1603:   if (!allowed) return <NoPerm title={editId ? 'تعديل التحويل' : 'تحويل جديد'} perm={editId ? 'transfers.update' : 'transfers.create'} go={go} />;
1604: 
1605:   const t = showQuery.data;
1606:   const same = from && to && from === to;
1607:   const upd = (key, p) => { setLines(ls => ls.map(l => l.key === key ? { ...l, ...p } : l)); setRowErrs({}); };
1608:   const lineBad = l => {
1609:     if (!l.variantId) return true;
1610:     const qv = toLatinDigits(l.req);
1611:     return !QTY_RE.test(qv) || !(Number(qv) > 0) || Number(qv) > QTY_MAX;
1612:   };
1613:   const valid = from && to && !same && lines.length && lines.length <= 100 && lines.every(l => !lineBad(l));
1614: 
1615:   const save = async () => {
1616:     setTried(true); if (!valid || busy || (editId && (!t || t.status !== 'draft'))) return;
1617:     setBusy(true); setSrvErr(null); setRowErrs({});
1618:     const payload = {
1619:       from_branch_id: from, to_branch_id: to, notes: note.trim() || null,
1620:       items: lines.map(l => ({
1621:         product_variant_id: l.variantId,
1622:         ...(l.fromLoc ? { from_location_id: l.fromLoc } : {}),
1623:         ...(l.toLoc ? { to_location_id: l.toLoc } : {}),
1624:         requested_qty: Number(toLatinDigits(l.req)),
1625:       })),
1626:     };
1627:     try {
1628:       if (editId) {
1629:         // PUT replaces items wholesale (TransferService::update) and is allowed in draft only.
1630:         await transfersApi.update(editId, payload);
1631:         toast('تم حفظ التعديلات'); go('transfer', { id: editId });
1632:       } else {
1633:         const res = await transfersApi.create(payload, keyFor(payload));
1634:         reset(); // new key only after success
1635:         toast(res.message || 'تم إنشاء التحويل بنجاح'); go('transfer', { id: res.data.id });
1636:       }
1637:     } catch (e) {
1638:       const ne = normalizeError(e);
1639:       setRowErrs({ ...ne.fields, ...groupItemsErrors(ne.fields) });
1640:       setSrvErr(ne.message);
1641:       setBusy(false);
1642:     }
1643:   };
1644: 
1645:   const shared = branchesQuery.data || [];
1646:   const branchOptions = shared.filter(b => b.is_active).map(b => ({ value: b.id, label: `${b.name} · ${b.type === 'warehouse' ? 'مخزن' : 'فرع'}` }));
1647:   const fromLocOpts = (fromLocsQuery.data || []).filter(l => l.is_active).map(l => ({ value: l.id, label: `${l.name} (${l.code})` }));
1648:   const toLocOpts = (toLocsQuery.data || []).filter(l => l.is_active).map(l => ({ value: l.id, label: `${l.name} (${l.code})` }));
1649:   const { phase, error } = editId ? apiPhase(showQuery, !t) : { phase: 'ready', error: undefined };
1650: 
1651:   return (
1652:     <section className="space-y-5">
1653:       <PageHead title={editId ? `تعديل ${t?.transfer_number || ''}` : 'تحويل جديد'} back={{ label: 'التحويلات المخزنية', onClick: () => go(editId ? 'transfer' : 'transfers', editId ? { id: editId } : {}) }}
1654:         actions={<><button className="btn btn-soft" onClick={() => go('transfers')}>إلغاء</button><button className="btn btn-dark" onClick={save} disabled={busy}>{busy && <span className="w-3.5 h-3.5 rounded-full border-2 border-current border-t-transparent animate-spin" />} حفظ كمسودة</button></>} />
1655: 
1656:       <Phase phase={phase} cols={4} error={error} onRetry={() => showQuery.reload()} onBack={() => go('transfers')}>
1657:         {editId && t && t.status !== 'draft' ? (
1658:           <Card><EmptyState icon="lock" title="التعديل مسموح في المسودة فقط" sub={`هذا التحويل بحالة «${TRANSFER_STATUS[t.status] || t.status}» ولا يقبل التعديل.`}
1659:             action={<button className="btn btn-dark btn-sm" onClick={() => go('transfer', { id: editId })}>فتح التحويل</button>} /></Card>
1660:         ) : (<>
1661:           <Card stagger={2}>
