1665:               </Field>
1666:               <button type="button" disabled={restriction.locked} onClick={() => { setFrom(to); setTo(from); setLines(ls => ls.map(l => ({ ...l, fromLoc: l.toLoc, toLoc: l.fromLoc }))); }} className="w-10 h-10 rounded-full v-subcard flex items-center justify-center c-orange mx-auto mb-0.5" title="تبديل">
1667:                 <Icon n="swap" s={16} />
1668:               </button>
