1670:                 <Sel value={to} onChange={v => { setTo(v || null); setLines(ls => ls.map(l => ({ ...l, toLoc: null }))); }} placeholder="إلى…" options={branchOptions} className={(tried && !to) || same ? 'err' : ''} />
1671:               </Field>
1672:             </div>
1673:             {same && <div className="mt-3"><InlineAlert kind="red" title="المصدر والوجهة متطابقان">العملية الحالية تشترط اختلاف فرع المصدر عن فرع الوجهة. للنقل بين مواقع داخل نفس الفرع استخدم التسوية.</InlineAlert></div>}
