1697:                           {re.requested_qty && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-red-text)' }}>{re.requested_qty}</div>}
1698:                         </td>
1699:                         <td className="pt-3"><button className="icon-btn" disabled={lines.length === 1} onClick={() => setLines(ls => ls.filter(x => x.key !== l.key))}><Icon n="trash" s={14} /></button></td>
1700:                       </tr>
1701:                     );
1702:                   })}
1703:                 </tbody>
1704:               </table>
1705:             </div>
1706:           </Card>
