2152: // Wrap list content with phase handling
2153: // List phases: loading | ready | empty | denied (403) |
2154: // notfound (404 + back to list) | conflict (409 banner + reload). Server
2155: // messages are Arabic — rendered verbatim, never translated.
2156: function Phase({ phase, cols, rows, empty, children, error, onRetry, onBack }) {
2157:   const { go } = useInv();
2158:   const back = onBack || (() => go('stock'));
2159:   if (phase === 'loading') return <SkeletonRows cols={cols} rows={rows} />;
2160:   if (phase === 'denied') return <NoPerm message={error?.message} go={back} />;
2161:   if (phase === 'notfound') return <Card><EmptyState icon="search" title="العنصر غير موجود" sub={error?.message || 'ربما تم حذفه.'} action={<button className="btn btn-dark btn-sm" onClick={back}>رجوع للقائمة</button>} /></Card>;
2162:   if (phase === 'conflict') return (<div className="space-y-4"><InlineAlert kind="amber" title="تعارض مع الخادم (409)"><p>{error?.message || 'تغيّرت البيانات على الخادم.'}</p><div className="mt-2"><button className="btn btn-dark btn-sm" onClick={onRetry}><Icon n="refresh" s={13} /> إعادة تحميل</button></div></InlineAlert>{children}</div>);
2163:   if (phase === 'error') return <ErrorState msg={error?.message} code={error?.status ? `HTTP ${error.status}` : undefined} onRetry={onRetry} />;
2164:   if (phase === 'empty') return empty;
2165:   return children;
2166: }
