2168: function InlineAlert({ kind = 'red', icon = 'alert', title, children, onClose }) {
2169:   const map = { red: ['--badge-red-bg', '--badge-red-text'], amber: ['--badge-amber-bg', '--badge-amber-text'], blue: ['--badge-blue-bg', '--badge-blue-text'], green: ['--badge-green-bg', '--badge-green-text'] }[kind];
2170:   return (
2171:     <div className="rounded-2xl px-4 py-3 flex items-start gap-3 fade-in" style={{ background: `var(${map[0]})` }}>
2172:       <span style={{ color: `var(${map[1]})` }} className="mt-0.5"><Icon n={icon} s={16} /></span>
2173:       <div className="flex-1 text-[12.5px]">
2174:         {title && <div className="font-semibold" style={{ color: `var(${map[1]})` }}>{title}</div>}
2175:         <div className="c-primary opacity-80 mt-0.5">{children}</div>
2176:       </div>
2177:       {onClose && <button onClick={onClose} className="c-secondary"><Icon n="x" s={14} /></button>}
2178:     </div>
2179:   );
2180: }
