2235: // ---------- Variant picker: product → variant/SKU (never stops at product) ----------
2236: // API-backed (Phase 3): GET production-receipts/options?search=, 300ms debounce,
2237: // max 50 active variants. Empty query shows "اكتب للبحث", never a fake full list.
2238: // Disabled variants are rejected by the server on input, so their absence here
2239: // is correct; to decrease a disabled variant, open stock → adjust with variantId.
2240: function VariantPicker({ value, onChange, placeholder = 'ابحث بالاسم أو SKU أو الباركود', small, exclude = [], allowClear }) {
2241:   const { variantCache } = useInv();
2242:   const [open, setOpen] = useState(false);
2243:   const [q, setQ] = useState('');
2244:   const [dq, setDq] = useState('');
2245:   const ref = useRef();
2246:   useEffect(() => {
2247:     // composedPath: the inventory shell renders inside a shadow root, where a document-level listener sees a retargeted target (the host) — contains() would always close. composedPath() crosses the boundary correctly.
2248:     const h = e => { const path = typeof e.composedPath === 'function' ? e.composedPath() : []; const inside = path.length ? path.includes(ref.current) : (ref.current && ref.current.contains(e.target)); if (!inside) setOpen(false); };
2249:     document.addEventListener('mousedown', h); return () => document.removeEventListener('mousedown', h);
2250:   }, []);
2251:   useEffect(() => { const t = setTimeout(() => setDq(q), 300); return () => clearTimeout(t); }, [q]);
2252:   const term = dq.trim();
2253:   const optsQuery = useApi(signal => term ? productionApi.options(term, signal) : Promise.resolve({ branches: [], variants: [] }), [term]);
2254:   const variants = useMemo(() => {
2255:     const list = (optsQuery.data?.variants || []).filter(v => !exclude.includes(v.id));
2256:     list.forEach(v => {
2257:       cacheVariantOptions(variantCache, [v]);
2258:     });
2259:     return list;
2260:   }, [optsQuery.data, exclude.join(',')]);
2261:   const cached = value ? variantCache.get(Number(value)) : null;
2262:   const label = cached?.name_ar || cached?.name_en || cached?.label || null;
2263:   const sku = cached?.sku || null;
2264: 
2265:   return (
2266:     <div ref={ref} className="relative">
2267:       <button type="button" onClick={() => setOpen(o => !o)} className={`inp ${small ? 'inp-sm' : ''} flex items-center justify-between gap-2 text-right`}>
2268:         {value ? (
2269:           <span className="flex items-center gap-2 min-w-0">
2270:             <span className="truncate c-primary">{label || `صنف #${value}`}</span>
2271:             {sku && <span className="mono text-[10.5px] px-1.5 py-0.5 rounded-md shrink-0" style={{ background: 'var(--icon-well-bg)' }} dir="ltr">{sku}</span>}
2272:           </span>
2273:         ) : <span className="c-muted truncate">{placeholder}</span>}
