 2: // Numbers arrive as strings with 4 decimals ("10.0000"): always Number() before
 3: // math, and formatQty() before display. See Branch/Location/StockLevel/
 4: // StockMovement/Stocktake/StockTransfer Resources + Transfer/Stocktake services.
 5: export type BranchType = 'branch' | 'warehouse';
 6: export type LocationType = 'shelf' | 'zone' | 'bin' | 'damaged' | 'receiving';
 7: export type TransferStatus = 'draft' | 'approved' | 'shipped' | 'received' | 'cancelled';
 8: export type StocktakeStatus = 'draft' | 'in_progress' | 'approved' | 'cancelled';
 9: export type AdjustmentType = 'increase' | 'decrease' | 'mark_damaged' | 'write_off_damaged' | 'restore_damaged';
10: export type StockMovementType =
11:   | 'production_receipt' | 'purchase_receipt' | 'sale' | 'sale_return'
12:   | 'adjustment_in' | 'adjustment_out' | 'damage' | 'damage_release' | 'damage_write_off'
13:   | 'transfer_out' | 'transfer_in' | 'transfer_in_transit' | 'transfer_transit_release' | 'transfer_shortage'
14:   | 'stocktake_gain' | 'stocktake_loss' | 'reserve' | 'release_reserve';
